// ── FETCH VALIDATED BEGINNING READINGS FOR EACH PUMP (shift carry-over) ─────────────
// Rule:
//   Shift 2 (second) → fetch validated Ending from Shift 1 (first)
//   Shift 1 (first)  → fetch validated Ending from Shift 2 (second)
//   Status must be: verified / approved / adjusted / validated
$last_readings_by_pump = [];     // pump_label => validated ending reading value
$pump_missing_prev     = [];     // pump_label => true  (flag: no validated prev found)
try {
    // Determine which shift/day to look back at
    // We detect current shift from session (fuel_shift_key is populated after line 318)
    // Use a two-pass approach: run after shift detection (we'll re-run below after shift is known)
    // Store a deferred closure pattern — actually set a flag, then run after shift variables are set
    $__fetch_prev_readings = function() use ($pdo, $station_id, &$last_readings_by_pump) {
        try {
            // Fetch latest present_reading (ending meter) for each pump from any valid/completed submission
            $latest_stmt = $pdo->prepare("
                SELECT ft.id, COALESCE(fp.pump_number, ft.fuel_type) AS pump_label, ft.fuel_type, ft.present_reading, ft.pump_id
                FROM fuel_transactions ft
                LEFT JOIN fuel_pumps fp ON ft.pump_id = fp.id
                WHERE ft.station_id = ?
                  AND LOWER(COALESCE(ft.status, '')) NOT IN ('voided', 'rejected', 'cancelled', 'canceled')
                  AND ft.present_reading > 0
                ORDER BY ft.transaction_date DESC, ft.id DESC
            ");
            $latest_stmt->execute([$station_id]);
            $latest_rows = $latest_stmt->fetchAll(PDO::FETCH_ASSOC);

            foreach ($latest_rows as $row) {
                $lbl = strtoupper(trim($row['pump_label'] ?? ''));
                $ft_name = strtoupper(trim($row['fuel_type'] ?? ''));
                $val = (float)$row['present_reading'];

                if ($lbl !== '' && !isset($last_readings_by_pump[$lbl])) {
                    $last_readings_by_pump[$lbl] = $val;
                    $last_readings_by_pump[preg_replace('/\s*-\s*/', ' - ', preg_replace('/\s+/', ' ', $lbl))] = $val;
                    $last_readings_by_pump[str_replace(' ', '', $lbl)] = $val;
                }
                if ($ft_name !== '' && !isset($last_readings_by_pump[$ft_name])) {
                    $last_readings_by_pump[$ft_name] = $val;
                    $last_readings_by_pump[preg_replace('/\s*-\s*/', ' - ', preg_replace('/\s+/', ' ', $ft_name))] = $val;
                    $last_readings_by_pump[str_replace(' ', '', $ft_name)] = $val;
                }
                if (!empty($row['pump_id'])) {
                    $p_key = 'PUMP_' . (int)$row['pump_id'];
                    if (!isset($last_readings_by_pump[$p_key])) {
                        $last_readings_by_pump[$p_key] = $val;
                    }
                }
            }
        } catch (Exception $e) {}
    };
} catch (Exception $e) {}

// ── Detect current shift period (STRICTLY REAL-TIME CLOCK DRIVEN) ─────────────
// Shift 1: 6:00 AM – 2:00 PM (06:00:00 – 13:59:59)
// Shift 2: 2:00 PM – 12:00 MN (14:00:00 – 05:59:59)
petron_init_dynamic_timezone();
$cur_hour = (int)date('G');

if ($cur_hour >= 6 && $cur_hour < 14) {
    $merch_shift_key  = 'first';
    $merch_shift_name = 'Shift 1';
} else {
    $merch_shift_key  = 'second';
    $merch_shift_name = 'Shift 2';
}

$active_shift = [
    'shift_key'   => $merch_shift_key,
    'shift_name'  => $merch_shift_name,
    'shift_order' => ($merch_shift_key === 'first' ? 1 : 2)
];

$fuel_shift_key  = $merch_shift_key;
$fuel_shift_name = $merch_shift_name;

// ── NOW run the deferred validated-beginning-reading fetch (needs $fuel_shift_key) ──
if (isset($__fetch_prev_readings) && is_callable($__fetch_prev_readings)) {
    $__fetch_prev_readings();
}

// ── Detect workflow state & pre-fetch saved readings for current date + shift ──────────
$today_date = date('Y-m-d');
$current_shift_status = 'DRAFT';
$today_saved_readings = [];
$is_closing_completed = false;

try {
    $shift_like_val = '%' . strtolower($fuel_shift_key) . '%';
    $stmt_cstat = $pdo->prepare("
        SELECT id, status, total_fuel_sales, net_sales, total_cash, total_cash_bank,
               cash_shift1, cash_shift2, ar_shift1, ar_shift2, total_ar, checked_by, verified_by
        FROM fuel_sales_closing
        WHERE station_id = ? AND report_date = ? AND (shift = ? OR shift_period = ? OR LOWER(shift) LIKE ?)
        ORDER BY id DESC LIMIT 1
    ");
    $stmt_cstat->execute([$station_id, $today_date, $fuel_shift_name, $fuel_shift_key, $shift_like_val]);
    $found_closing = $stmt_cstat->fetch(PDO::FETCH_ASSOC);
    if ($found_closing && !empty($found_closing['status'])) {
        $current_shift_status = strtoupper(trim($found_closing['status']));
    }
} catch (Exception $e) {}

// A closing is truly completed ONLY if actual financial data was submitted/saved OR ?closing_saved is present.
// Note: Stubs created during meter reading encoding have 0.00 sales and are NOT completed closings!
$has_closing_data = false;
if (!empty($found_closing)) {
    $has_closing_data = (
        (float)($found_closing['total_fuel_sales'] ?? 0) > 0 ||
        (float)($found_closing['net_sales'] ?? 0) > 0 ||
        (float)($found_closing['total_cash'] ?? 0) > 0 ||
        (float)($found_closing['total_cash_bank'] ?? 0) > 0 ||
        (float)($found_closing['cash_shift1'] ?? 0) > 0 ||
        (float)($found_closing['cash_shift2'] ?? 0) > 0 ||
        (float)($found_closing['ar_shift1'] ?? 0) > 0 ||
        (float)($found_closing['ar_shift2'] ?? 0) > 0 ||
        (float)($found_closing['total_ar'] ?? 0) > 0 ||
        !empty(trim($found_closing['checked_by'] ?? ''))
    );
}

if (isset($_GET['closing_saved']) || ($has_closing_data && in_array($current_shift_status, ['CLOSING_COMPLETED', 'SAVED', 'REPORTED', 'VERIFIED', 'APPROVED', 'VALIDATED']))) {
    $is_closing_completed = true;
    $current_shift_status = 'CLOSING_COMPLETED';
} else {
    $is_closing_completed = false;
    if ($current_shift_status === 'CLOSING_COMPLETED' || $current_shift_status === 'VERIFIED') {
        // If it was just an empty stub marked Verified/Completed without closing figures, treat status as READINGS_SUBMITTED
        $current_shift_status = 'READINGS_SUBMITTED';
    }
}

if (!$is_closing_completed && ($current_shift_status === 'DRAFT' || empty($current_shift_status))) {
    try {
        $stmt_txstat = $pdo->prepare("
            SELECT status FROM fuel_transactions
            WHERE station_id = ? AND DATE(transaction_date) = ? AND shift_period = ?
              AND LOWER(COALESCE(status,'')) NOT IN ('rejected','voided','cancelled','canceled')
            ORDER BY id DESC LIMIT 1
        ");
        $stmt_txstat->execute([$station_id, $today_date, $fuel_shift_key]);
        $found_txstat = $stmt_txstat->fetchColumn();
        if ($found_txstat) {
            $current_shift_status = strtoupper(trim($found_txstat));
        }
    } catch (Exception $e) {}
}

try {
    $st_readings = $pdo->prepare("
        SELECT ft.id, COALESCE(NULLIF(fp.pump_number, ''), ft.fuel_type) AS pump_label, ft.fuel_type, ft.pump_id,
               ft.present_reading, ft.previous_reading, ft.calibration, ft.liters_sold, ft.total_amount, ft.status
        FROM fuel_transactions ft
        LEFT JOIN fuel_pumps fp ON ft.pump_id = fp.id
        WHERE ft.station_id = ?
          AND DATE(ft.transaction_date) = ?
          AND (ft.shift_period = ? OR ft.shift_name = ?)
          AND LOWER(COALESCE(ft.status,'')) NOT IN ('rejected','voided','cancelled','canceled')
        ORDER BY ft.id ASC
    ");
    $st_readings->execute([$station_id, $today_date, $fuel_shift_key, $fuel_shift_name]);
    $saved_rows = $st_readings->fetchAll(PDO::FETCH_ASSOC);
    foreach ($saved_rows as $sr) {
        $lbl_u = strtoupper(trim($sr['pump_label'] ?? ''));
        $ft_u  = strtoupper(trim($sr['fuel_type'] ?? ''));
        if ($lbl_u !== '') {
            $today_saved_readings[$lbl_u] = $sr;
            $today_saved_readings[preg_replace('/\s*-\s*/', ' - ', preg_replace('/\s+/', ' ', $lbl_u))] = $sr;
            $today_saved_readings[str_replace(' ', '', $lbl_u)] = $sr;
        }
        if ($ft_u !== '') {
            $today_saved_readings[$ft_u]  = $sr;
            $today_saved_readings[preg_replace('/\s*-\s*/', ' - ', preg_replace('/\s+/', ' ', $ft_u))] = $sr;
            $today_saved_readings[str_replace(' ', '', $ft_u)] = $sr;
        }
        if (!empty($sr['pump_id'])) {
            $today_saved_readings['PUMP_' . (int)$sr['pump_id']] = $sr;
        }
    }
} catch (Exception $e) {}

// Check if current shift has submitted readings awaiting closing input
// The Fuel Sales Closing button appears when readings have been submitted AND closing is not completed!
$has_submitted_readings_unclosed = false;
if (!$is_closing_completed) {
    if (!empty($saved_rows)) {
        foreach ($saved_rows as $sr) {
            if ((float)($sr['present_reading'] ?? 0) > 0) {
                $has_submitted_readings_unclosed = true;
                break;
            }
        }
    }
    if (!$has_submitted_readings_unclosed && !empty($today_saved_readings)) {
        foreach ($today_saved_readings as $sr) {
            if ((float)($sr['present_reading'] ?? 0) > 0) {
                $has_submitted_readings_unclosed = true;
                break;
            }
        }
    }
    // Also if a closing stub exists without completed financial data
    if (!$has_submitted_readings_unclosed && !empty($found_closing)) {
        $has_submitted_readings_unclosed = true;
    }
}

// ── STAFF DASHBOARD KPI CARDS DATA ────────────────────────────────────────────
$staff_kpi = [
    'orders_today' => 0,
    'merchandise_released' => 0,
    'total_amount' => 0.00,
    'completed_jobs' => 0
];

try {
    $today_start = date('Y-m-d 00:00:00');
    $today_end = date('Y-m-d 23:59:59');
    
    // Orders Today (merchandise transactions)
    $stmt = $pdo->prepare("SELECT COUNT(*) FROM merchandise_transactions WHERE staff_id = ? AND transaction_date BETWEEN ? AND ?");
    $stmt->execute([$me['id'], $today_start, $today_end]);
    $staff_kpi['orders_today'] = (int)$stmt->fetchColumn();
    
    // Merchandise Released (total quantity)
    $stmt = $pdo->prepare("SELECT COALESCE(SUM(quantity), 0) FROM merchandise_transactions WHERE staff_id = ? AND transaction_date BETWEEN ? AND ?");
    $stmt->execute([$me['id'], $today_start, $today_end]);
    $staff_kpi['merchandise_released'] = (int)$stmt->fetchColumn();
    
    // Total Amount Encoded
    $stmt = $pdo->prepare("SELECT COALESCE(SUM(total_amount), 0) FROM merchandise_transactions WHERE staff_id = ? AND transaction_date BETWEEN ? AND ?");
    $stmt->execute([$me['id'], $today_start, $today_end]);
    $staff_kpi['total_amount'] = (float)$stmt->fetchColumn();
    
    // Completed Job Orders
    $stmt = $pdo->prepare("SELECT COUNT(*) FROM job_orders WHERE (user_id = ? OR created_by = ?) AND status = 'Completed' AND DATE(completed_at) = CURDATE()");
    $stmt->execute([$me['id'], $me['id']]);
    $staff_kpi['completed_jobs'] = (int)$stmt->fetchColumn();
} catch (Exception $e) {
    error_log("Staff KPI error: " . $e->getMessage());
}

// ── Recent shift transactions (history tab) ───────────────────────────────────
$recent_fuel      = [];
$recent_merch       = [];
$available_shifts   = [];
$shift_log          = [];
$merch_total_count  = 0;
$filter_shift       = $_GET['shift'] ?? '';
$filter_date        = $_GET['date']  ?? '';
$hist_page          = max(1, (int)($_GET['page'] ?? 1));
$hist_per_page      = 50;
