            // Pagination Footer (Only if Total Records > 10)
            if (totalRows > 10) {
                var showingStart = (window.todayEntriesPage - 1) * window.todayEntriesPageSize + 1;
                var showingEnd = Math.min(window.todayEntriesPage * window.todayEntriesPageSize, totalRows);
                
                html += `
