                    <datalist id="productUnitList">
                        <option value="pcs">
                        <option value="bottle">
                        <option value="pack">
                        <option value="box">
                        <option value="can">
                        <option value="bag">
                        <option value="liter">
                        <option value="kg">
                        <option value="pair">
                        <option value="set">
                    </datalist>
                </div>

                <!-- Unit Price -->
                <div style="margin-bottom:14px;">
                    <label style="font-size:11px;font-weight:600;color:#475569;display:block;margin-bottom:5px;">
                        Unit Price (₱) <span style="color:#dc2626;">*</span>
                    </label>
                    <input type="number" id="newProductPrice" class="txn-input"
                           placeholder="0.00"
                           min="0"
                           step="0.01"
                           oninput="resetProductInputValidation(this);"
                           style="font-size:13px;"
                           autocomplete="off">
                </div>

                <!-- Reason for Request -->
                <div style="margin-bottom:18px;">
                    <label style="font-size:11px;font-weight:600;color:#475569;display:block;margin-bottom:5px;">
                        Reason for Request <span style="color:#dc2626;">*</span>
                    </label>
                    <textarea id="newProductReason" class="txn-input"
                              placeholder="Why do you need this product added? (e.g., 'Customer is looking for this item')"
                              rows="2"
                              maxlength="500"
                              oninput="resetProductInputValidation(this);"
                              style="font-size:13px;resize:vertical;"
                              autocomplete="off"></textarea>
                </div>

                <!-- Error message -->
                <div id="addProductError"
                     style="display:none;background:#fee2e2;border:1px solid #fca5a5;
                            border-radius:8px;padding:10px 12px;margin-bottom:14px;
                            font-size:12px;color:#991b1b;display:flex;align-items:flex-start;gap:8px;">
                    <i class="fas fa-exclamation-circle"></i>
                    <span id="addProductErrorText"></span>
                </div>

                <!-- Buttons -->
                <div style="display:flex;gap:10px;justify-content:flex-end;">
                    <button type="button" onclick="closeAddProductModal()"
                            class="txn-btn secondary">
                        Cancel
                    </button>
                    <button type="button" id="addProductSubmitBtn"
                            onclick="submitNewProduct()"
                            class="txn-btn primary">
                        <i class="fas <?= in_array($role, ['admin','superadmin']) ? 'fa-plus-circle' : 'fa-paper-plane' ?>"></i> <?= in_array($role, ['admin','superadmin']) ? 'Add Product' : 'Submit for Approval' ?>
                    </button>
                </div>
            </div>
        </div>

        <!-- ══ MERCHANDISE TRANSACTION JAVASCRIPT ══════════════════════════ -->
        <script>
        // ── State ────────────────────────────────────────────────────────────
        let cart = [];
        window.cart = cart;
        window.getPetronCart = function() { return cart; };
        window.setPetronCart = function(c) {
            if (Array.isArray(c)) {
                cart = c;
                window.cart = c;
                if (typeof renderCart === 'function') renderCart();
                if (typeof updateCheckoutBtn === 'function') updateCheckoutBtn();
            closeProductDropdown();
                if (typeof onPaymentChange === 'function') onPaymentChange();
            }
        };
        let selectedProduct = null;
        const stationTaxConfig = <?= json_encode($station_tax_cfg) ?>;
        const pointsPerAmount = <?= (float)$points_per_amount ?>;
        const redemptionValue  = <?= (float)$redemption_value ?>;
        const minimumRedeemPoints = <?= (int)$minimum_redeem_points ?>;
        const selectedCustomerIds = { jo: null, merch: null };

        function getLoyaltyProgramConfig() {
            const progSelect = document.getElementById('loyaltyProgram');
            const selOpt = (progSelect && progSelect.selectedIndex >= 0) ? progSelect.options[progSelect.selectedIndex] : null;
            const pPerAmt = selOpt && selOpt.dataset.pointsPerAmount ? parseFloat(selOpt.dataset.pointsPerAmount) : pointsPerAmount;
            const rVal = selOpt && selOpt.dataset.redemptionValue ? parseFloat(selOpt.dataset.redemptionValue) : redemptionValue;
            const minPts = selOpt && selOpt.dataset.minPoints ? parseInt(selOpt.dataset.minPoints, 10) : minimumRedeemPoints;
            return {
                name: progSelect ? progSelect.value : 'No Loyalty',
                pointsPerAmount: (pPerAmt > 0) ? pPerAmt : 100.00,
                redemptionValue: (rVal > 0) ? rVal : 1.00,
                minPoints: (minPts >= 0) ? minPts : 1
            };
        }

        window.getGrossTotal = function getGrossTotal() {
            const currentCart = Array.isArray(window.cart) ? window.cart : (typeof cart !== 'undefined' && Array.isArray(cart) ? cart : []);
            let subtotal = currentCart.reduce((s, i) => s + (parseFloat(i.quantity) || 0) * (parseFloat(i.unit_price) || 0), 0);

            // Seamlessly incorporate Job Order service fee and tip if entered in form and not yet committed to cart
            const hasServiceInCart = currentCart.some(i => i.item_type === 'service');
            if (!hasServiceInCart) {
                const formSvcType = (document.getElementById('joServiceTypeValue')?.value || document.getElementById('joServiceType')?.value || '').trim();
                const formSvcPrice = parseFloat(document.getElementById('joServicePrice')?.value || 0) || 0;
                const formLaborPrice = parseFloat((document.getElementById('joLaborCharge')?.value || '0').replace(/[^0-9.]/g, '')) || 0;
                if (formSvcType && (formSvcPrice > 0 || formLaborPrice > 0)) {
                    subtotal += (formSvcPrice + formLaborPrice);
                }
            }

            // Selling prices are already VAT-inclusive. Do NOT multiply by 1.12.
            return Math.round(subtotal * 100) / 100;
        };

        window.getLoyaltyDiscount = function getLoyaltyDiscount(grossTotal) {
            const payMethod = document.getElementById('paymentMethod')?.value || '';
            const isPvc = (payMethod === 'Petron Value Card (PVC Points)');
            const program = document.getElementById('loyaltyProgram')?.value || 'No Loyalty';
            const applyCheckbox = document.getElementById('loyaltyApplyRedemption');
            
            if (!isPvc && (program === 'No Loyalty' || !applyCheckbox || !applyCheckbox.checked)) return 0;
            
            let balance = 0;
            if (isPvc) {
                balance = parseInt(document.getElementById('pvcAvailablePoints')?.value || '0', 10) || 0;
            } else {
                balance = parseInt(document.getElementById('loyaltyPointsBalance')?.value || '0', 10) || 0;
            }
            
            const config = getLoyaltyProgramConfig();
            const convRate = (typeof pvcConversionRate === 'number' && pvcConversionRate > 0) ? pvcConversionRate : (config.redemptionValue || 1.0);
            if (balance <= 0) return 0;

            const gross = (typeof grossTotal === 'number' && grossTotal >= 0) ? grossTotal : getGrossTotal();
            if (gross <= 0) return 0;

            const maxPointsNeeded = Math.ceil(gross / convRate);
            const validPoints = Math.min(balance, maxPointsNeeded);
            const discount = Math.min(gross, Math.round(validPoints * convRate * 100) / 100);
            return discount;
        };

        window.getGrandTotal = function getGrandTotal() {
            const gross = getGrossTotal();
            const discount = getLoyaltyDiscount(gross);
            return Math.max(0, Math.round((gross - discount) * 100) / 100);
        };

        window.applyCustomerLoyalty = function applyCustomerLoyalty(customer) {
            if (!customer) return;
            const loyaltyDropdown = document.getElementById('loyaltyProgram');
            const loyaltyCardNoInput = document.getElementById('loyaltyCardNo');
            const loyaltyCardDisplay = document.getElementById('loyaltyCardDisplay');
            const loyaltyPointsBalanceEl = document.getElementById('loyaltyPointsBalance');
            const loyaltyAccountStatus = document.getElementById('loyaltyAccountStatus');
            const eligibilityBadge = document.getElementById('loyaltyEligibilityBadge');
            const applyCheckbox = document.getElementById('loyaltyApplyRedemption');

            // Authoritative PVC card info
            const cardVal = (customer.pvc_card_number || customer.loyalty_card_no || '').trim();
            const pts = parseInt(customer.pvc_points_balance ?? customer.points ?? 0, 10) || 0;
            const hasPvcCard = customer.has_pvc_card === true || (cardVal !== '');
            const isAccountActive = (customer.loyalty_status || 'active').toLowerCase() === 'active';

            // Sync PVC panel
            const pvcCardDisplay = document.getElementById('pvcCardNumberDisplay');
            const pvcAvailEl = document.getElementById('pvcAvailablePoints');
            const pvcNotice = document.getElementById('pvcCustomerNotice');
            if (pvcCardDisplay) pvcCardDisplay.value = hasPvcCard ? cardVal : 'No linked PVC card';
            if (pvcAvailEl) pvcAvailEl.value = hasPvcCard ? pts : 0;
            if (pvcNotice) pvcNotice.style.display = hasPvcCard ? 'none' : 'block';

            const payMethod = document.getElementById('paymentMethod')?.value || '';

            if (hasPvcCard) {
                if (loyaltyDropdown) {
                    if (loyaltyDropdown.value === 'No Loyalty' && loyaltyDropdown.options.length > 1) {
                        loyaltyDropdown.selectedIndex = 1;
                    }
                }
                if (loyaltyCardNoInput) loyaltyCardNoInput.value = cardVal;
                if (loyaltyCardDisplay) loyaltyCardDisplay.textContent = 'PVC Card: ' + cardVal;
                if (loyaltyPointsBalanceEl) loyaltyPointsBalanceEl.value = pts;

                const config = getLoyaltyProgramConfig();
                const isEligible = isAccountActive && pts >= config.minPoints;

                if (loyaltyAccountStatus) {
                    loyaltyAccountStatus.innerHTML = isAccountActive 
                        ? '<i class="fas fa-check-circle" style="color:#16a34a;"></i> <span style="color:#16a34a;">Active Account</span>' 
                        : '<i class="fas fa-times-circle" style="color:#dc2626;"></i> <span style="color:#dc2626;">Inactive</span>';
                }
                if (eligibilityBadge) {
                    eligibilityBadge.style.display = 'inline-block';
                    if (isEligible) {
                        eligibilityBadge.style.background = '#dcfce7';
                        eligibilityBadge.style.color = '#166534';
                        eligibilityBadge.textContent = 'Eligible (' + pts + ' pts)';
                    } else if (pts < config.minPoints) {
                        eligibilityBadge.style.background = '#fef3c7';
                        eligibilityBadge.style.color = '#92400e';
                        eligibilityBadge.textContent = 'Min ' + config.minPoints + ' pt to redeem';
                    } else {
                        eligibilityBadge.style.background = '#fee2e2';
                        eligibilityBadge.style.color = '#991b1b';
                        eligibilityBadge.textContent = 'Ineligible';
                    }
                }

                if (applyCheckbox) {
                    applyCheckbox.disabled = !isEligible;
                    if (!isEligible) applyCheckbox.checked = false;
                }
                onLoyaltyChange();
            } else {
                if (loyaltyDropdown) loyaltyDropdown.value = 'No Loyalty';
                if (loyaltyCardNoInput) loyaltyCardNoInput.value = '';
                if (loyaltyCardDisplay) loyaltyCardDisplay.textContent = 'Card: None';
                if (loyaltyPointsBalanceEl) loyaltyPointsBalanceEl.value = 0;
                if (eligibilityBadge) {
                    eligibilityBadge.style.display = 'inline-block';
                    eligibilityBadge.style.background = '#f1f5f9';
                    eligibilityBadge.style.color = '#64748b';
                    eligibilityBadge.textContent = 'No PVC Account';
                }
                if (applyCheckbox) {
                    applyCheckbox.checked = false;
                    applyCheckbox.disabled = true;
                }
                onLoyaltyChange();
            }

            if (payMethod === 'Petron Value Card (PVC Points)') {
                calcLoyaltyPoints();
            }
        };

        window.onLoyaltyChange = function onLoyaltyChange() {
            const program = document.getElementById('loyaltyProgram')?.value || 'No Loyalty';
            const fieldsWrap = document.getElementById('loyaltyFields');
            const cardNoInput = document.getElementById('loyaltyCardNo');
            const cardDisplay = document.getElementById('loyaltyCardDisplay');
            const balanceInput = document.getElementById('loyaltyPointsBalance');
            const discountInput = document.getElementById('loyaltyDiscountAmount');
            const discRow = document.getElementById('cartLoyaltyDiscountRow');
            const discVal = document.getElementById('cartLoyaltyDiscount');
            const applyCheckbox = document.getElementById('loyaltyApplyRedemption');
            const eligibilityBadge = document.getElementById('loyaltyEligibilityBadge');

            if (fieldsWrap) {
                if (program !== 'No Loyalty') {
                    fieldsWrap.style.display = 'block';
                    if (eligibilityBadge && eligibilityBadge.textContent.trim() === 'Not Verified') {
                        eligibilityBadge.style.display = 'inline-block';
                    }
                    calcLoyaltyPoints();
                } else {
                    fieldsWrap.style.display = 'none';
                    if (cardNoInput) cardNoInput.value = '';
                    if (cardDisplay) cardDisplay.textContent = 'Card: None';
                    if (balanceInput) balanceInput.value = '0';
                    if (applyCheckbox) {
                        applyCheckbox.checked = false;
                        applyCheckbox.disabled = true;
                    }
                    if (eligibilityBadge) eligibilityBadge.style.display = 'none';
                    const pointsEarned = document.getElementById('loyaltyPointsEarned');
                    const pointsRedeemed = document.getElementById('loyaltyPointsRedeemed');
                    const pointsRemaining = document.getElementById('loyaltyPointsRemaining');
                    const pointsAfter = document.getElementById('loyaltyPointsAfter');
                    if (pointsEarned) pointsEarned.value = '0';
                    if (pointsRedeemed) pointsRedeemed.value = '0';
                    if (pointsRemaining) pointsRemaining.value = '0';
                    if (pointsAfter) pointsAfter.value = '0';
                    if (discountInput) discountInput.value = '₱0.00';
                    if (discRow) discRow.style.display = 'none';
                    if (discVal) discVal.textContent = '-₱0.00';
                    calcLoyaltyPoints();
                }
            }
        };

        function updateLoyaltyPointsEarned(grand) {
            const payMethod = document.getElementById('paymentMethod')?.value || '';
            const program = document.getElementById('loyaltyProgram')?.value || 'No Loyalty';
            const pointsEarnedInput = document.getElementById('loyaltyPointsEarned');
            const config = getLoyaltyProgramConfig();
            if (program === 'No Loyalty') {
                if (pointsEarnedInput) pointsEarnedInput.value = 0;
            } else if (pointsEarnedInput) {
                const netAmount = (typeof grand === 'number' && grand >= 0) ? grand : getGrandTotal();
                const pts = Math.floor(netAmount / config.pointsPerAmount);
                pointsEarnedInput.value = Math.max(0, pts);
            }
            calcLoyaltyPoints();
        }

        window.calcLoyaltyPoints = function calcLoyaltyPoints() {
            const payMethod = document.getElementById('paymentMethod')?.value || '';
            const isPvc = (payMethod === 'Petron Value Card (PVC Points)');
            const program = document.getElementById('loyaltyProgram')?.value || 'No Loyalty';
            const balanceInput = document.getElementById('loyaltyPointsBalance');
            const earnedInput = document.getElementById('loyaltyPointsEarned');
            const redeemedInput = document.getElementById('loyaltyPointsRedeemed');
            const remainingInput = document.getElementById('loyaltyPointsRemaining');
            const afterInput = document.getElementById('loyaltyPointsAfter');
            const discountInput = document.getElementById('loyaltyDiscountAmount');
            const discRow = document.getElementById('cartLoyaltyDiscountRow');
            const discVal = document.getElementById('cartLoyaltyDiscount');
            const errorEl = document.getElementById('loyaltyErrorMsg');
            const grandEl = document.getElementById('cartGrandTotal');
            const applyCheckbox = document.getElementById('loyaltyApplyRedemption');
            const rateBadge = document.getElementById('loyaltyRateBadge');
            const hintEl = document.getElementById('loyaltyRedeemHint');
            const eligibilityBadge = document.getElementById('loyaltyEligibilityBadge');

            const gross = getGrossTotal();
            const config = getLoyaltyProgramConfig();
            const convRate = (typeof pvcConversionRate === 'number' && pvcConversionRate > 0) ? pvcConversionRate : (config.redemptionValue || 1.0);

            if (rateBadge) {
                rateBadge.textContent = `1 pt = ₱${fmtNum(convRate)}`;
            }

            // ── HANDLE PVC POINTS PAYMENT METHOD ──────────────────────────────
            if (isPvc) {
                const pvcCardDisplay = document.getElementById('pvcCardNumberDisplay');
                const pvcAvailEl = document.getElementById('pvcAvailablePoints');
                const pvcNotice = document.getElementById('pvcCustomerNotice');
                const pvcPointsRedeemedEl = document.getElementById('pvcPointsRedeemed');
                const pvcDiscountEl = document.getElementById('pvcDiscountDisplay');
                const pvcPointsAfterEl = document.getElementById('pvcPointsAfter');
                const pvcRemainingEl = document.getElementById('pvcRemainingBalanceDisplay');

                let currentBalance = 0;
                let activeCustomer = null;
                const custId = selectedCustomerIds.jo || selectedCustomerIds.merch;
                if (custId && Array.isArray(customerData)) {
                    activeCustomer = customerData.find(c => c.id == custId);
                }

                if (activeCustomer && activeCustomer.has_pvc_card) {
                    currentBalance = parseInt(activeCustomer.pvc_points_balance || activeCustomer.points || 0, 10) || 0;
                    if (pvcCardDisplay) pvcCardDisplay.value = activeCustomer.pvc_card_number;
                    if (pvcAvailEl) pvcAvailEl.value = currentBalance;
                    if (pvcNotice) pvcNotice.style.display = 'none';
                } else if (pvcAvailEl) {
                    currentBalance = parseInt(pvcAvailEl.value || '0', 10) || 0;
                    if (pvcNotice) pvcNotice.style.display = (!activeCustomer || !activeCustomer.has_pvc_card) ? 'block' : 'none';
                }

                const maxPointsNeeded = gross > 0 ? Math.ceil(gross / convRate) : 0;
                const pointsRedeemed = Math.min(currentBalance, maxPointsNeeded);
                const discount = Math.min(gross, Math.round(pointsRedeemed * convRate * 100) / 100);
                const remainingBalance = Math.max(0, Math.round((gross - discount) * 100) / 100);
                const remainingPoints = Math.max(0, currentBalance - pointsRedeemed);

                if (pvcPointsRedeemedEl) pvcPointsRedeemedEl.value = pointsRedeemed;
                if (pvcDiscountEl) pvcDiscountEl.value = '₱' + fmtNum(discount);
                if (pvcPointsAfterEl) pvcPointsAfterEl.value = remainingPoints;
                if (pvcRemainingEl) pvcRemainingEl.value = '₱' + fmtNum(remainingBalance);

                if (redeemedInput) redeemedInput.value = pointsRedeemed;
                if (remainingInput) remainingInput.value = remainingPoints;
                if (discountInput) discountInput.value = '₱' + fmtNum(discount);
                if (balanceInput) balanceInput.value = currentBalance;

                if (discRow && discVal) {
                    if (discount > 0) {
                        discRow.style.display = 'flex';
                        discVal.textContent = '-₱' + fmtNum(discount);
                    } else {
                        discRow.style.display = 'none';
                        discVal.textContent = '-₱0.00';
                    }
                }
                if (grandEl) grandEl.textContent = '₱' + fmtNum(remainingBalance);

                // Points Earned on remaining monetary amount paid only (0 if fully covered by PVC points)
                const pointsEarned = Math.floor(remainingBalance / config.pointsPerAmount);
                if (earnedInput) earnedInput.value = Math.max(0, pointsEarned);
                if (afterInput) afterInput.value = Math.max(0, remainingPoints + pointsEarned);

                if (errorEl) errorEl.style.display = 'none';
                if (typeof computeChange === 'function') computeChange();
                if (typeof onPaymentAmountInput === 'function') onPaymentAmountInput();
                if (typeof updatePaymentStatusBadge === 'function') updatePaymentStatusBadge();
                if (typeof updateCheckoutBtn === 'function') updateCheckoutBtn();
                return;
            }

            // ── HANDLE OTHER PAYMENT METHODS (Cash, Card, E-Wallet, Credit) ───
            if (program === 'No Loyalty') {
                if (redeemedInput) redeemedInput.value = 0;
                if (remainingInput) remainingInput.value = 0;
                if (earnedInput) earnedInput.value = 0;
                if (afterInput) afterInput.value = 0;
                if (discountInput) discountInput.value = '₱0.00';
                if (discRow) discRow.style.display = 'none';
                if (errorEl) errorEl.style.display = 'none';
                if (grandEl) grandEl.textContent = '₱' + fmtNum(gross);
                if (eligibilityBadge) eligibilityBadge.style.display = 'none';
                if (applyCheckbox) {
                    applyCheckbox.checked = false;
                    applyCheckbox.disabled = true;
                }
                if (typeof computeChange === 'function') computeChange();
                if (typeof onPaymentAmountInput === 'function') onPaymentAmountInput();
                if (typeof updatePaymentStatusBadge === 'function') updatePaymentStatusBadge();
                return;
            }

            const currentBalance = parseInt(balanceInput?.value || '0', 10) || 0;
            const isEligible = currentBalance >= config.minPoints;

            if (applyCheckbox) {
                applyCheckbox.disabled = !isEligible || gross <= 0;
                if (!isEligible || gross <= 0) {
                    applyCheckbox.checked = false;
                }
            }

            let pointsRedeemed = 0;
            let discount = 0;

            if (applyCheckbox && applyCheckbox.checked && isEligible && gross > 0) {
                const maxPointsNeeded = Math.ceil(gross / convRate);
                pointsRedeemed = Math.min(currentBalance, maxPointsNeeded);
                discount = Math.min(gross, Math.round(pointsRedeemed * convRate * 100) / 100);
                if (hintEl) {
                    hintEl.textContent = `Redeeming ${pointsRedeemed} pts for ₱${fmtNum(discount)} discount.`;
                    hintEl.style.color = '#15803d';
                }
            } else {
                pointsRedeemed = 0;
                discount = 0;
                if (hintEl) {
                    hintEl.textContent = isEligible 
                        ? `Enable to automatically redeem up to ${currentBalance} available points.`
                        : `Minimum ${config.minPoints} point required to redeem. Current balance: ${currentBalance} pts.`;
                    hintEl.style.color = '#64748b';
                }
            }

            const remainingPoints = Math.max(0, currentBalance - pointsRedeemed);
            const netGrand = Math.max(0, Math.round((gross - discount) * 100) / 100);

            if (redeemedInput) redeemedInput.value = pointsRedeemed;
            if (remainingInput) remainingInput.value = remainingPoints;
            if (discountInput) discountInput.value = '₱' + fmtNum(discount);

            if (discRow && discVal) {
                if (discount > 0) {
                    discRow.style.display = 'flex';
                    discVal.textContent = '-₱' + fmtNum(discount);
                } else {
                    discRow.style.display = 'none';
                    discVal.textContent = '-₱0.00';
                }
            }
            if (grandEl) grandEl.textContent = '₱' + fmtNum(netGrand);

            // Points Earned = Math.floor(netGrand / pointsPerAmount) (₱100 eligible purchase = 1 point)
            const pointsEarned = Math.floor(netGrand / config.pointsPerAmount);
            if (earnedInput) earnedInput.value = Math.max(0, pointsEarned);

            // Points After = Remaining Points + Points Earned
            const pointsAfter = remainingPoints + pointsEarned;
            if (afterInput) afterInput.value = Math.max(0, pointsAfter);

            if (errorEl) errorEl.style.display = 'none';

            // Update eligibility badge
            if (eligibilityBadge) {
                eligibilityBadge.style.display = 'inline-block';
                if (isEligible) {
                    eligibilityBadge.style.background = '#dcfce7';
                    eligibilityBadge.style.color = '#166534';
                    eligibilityBadge.textContent = 'Eligible (' + currentBalance + ' pts)';
                } else {
                    eligibilityBadge.style.background = '#fef3c7';
                    eligibilityBadge.style.color = '#92400e';
                    eligibilityBadge.textContent = 'Min ' + config.minPoints + ' pt to redeem';
                }
            }

            const checkoutBtn = document.getElementById('checkoutBtn');
            if (checkoutBtn && typeof updateCheckoutBtn === 'function') {
                updateCheckoutBtn();
            }
            if (typeof computeChange === 'function') computeChange();
            if (typeof onPaymentAmountInput === 'function') onPaymentAmountInput();
            if (typeof updatePaymentStatusBadge === 'function') updatePaymentStatusBadge();
        };

        window.calcFleetRewards = function calcFleetRewards() {
            const fcAmountInput = document.getElementById('fcAmount');
            const balanceInput = document.getElementById('fcRewardsBalance');
            const earnedInput = document.getElementById('fcPointsEarned');
            const redeemedInput = document.getElementById('fcPointsRedeemed');
            const afterInput = document.getElementById('fcPointsAfter');

            const amount = parseFloat(fcAmountInput?.value || 0) || 0;
            const currentBalance = parseInt(balanceInput?.value || 0, 10) || 0;
            const ptsEarned = (amount > 0 && typeof pointsPerAmount !== 'undefined' && pointsPerAmount > 0)
                ? Math.floor(amount / pointsPerAmount)
                : 0;
            if (earnedInput) earnedInput.value = ptsEarned;

            let ptsRedeemed = parseInt(redeemedInput?.value || 0, 10) || 0;
            if (ptsRedeemed < 0) {
                ptsRedeemed = 0;
                if (redeemedInput) redeemedInput.value = 0;
            }

            const remaining = Math.max(0, currentBalance + ptsEarned - ptsRedeemed);
            if (afterInput) afterInput.value = remaining;
        };

        document.addEventListener('DOMContentLoaded', () => {
            document.getElementById('loyaltyCardNo')?.addEventListener('input', function() {
                const cardNo = this.value.trim().toLowerCase();
                const balanceInput = document.getElementById('loyaltyPointsBalance');
                if (!balanceInput) return;
                if (!cardNo) {
                    balanceInput.value = '0';
                    return;
                }
                const found = customerData.find(c => 
                    (c.customer_id && c.customer_id.toLowerCase() === cardNo) || 
                    (c.id_number && c.id_number.toLowerCase() === cardNo)
                );
                if (found) {
                    balanceInput.value = found.points || 0;
                } else {
                    balanceInput.value = '0';
                }
            });
        });

        // ── Product dropdown (body-portal: teleport to body so it's never clipped) ─
        (function initProductDropdownPortal() {
            function forceHideProductDropdown() {
                var list = document.getElementById('productDropdownList');
                var wrap = document.getElementById('productDropdownWrap');
                if (list) {
                    list.classList.remove('is-open');
                    list.style.display = 'none';
                }
                if (list && wrap && list.parentElement !== document.body) {
                    document.body.appendChild(list);
                    list.style.position = 'fixed';
                    list.style.zIndex = '99999';
                }
                if (list) {
                    list.classList.remove('is-open');
                    list.style.display = 'none';
                }
            }
            document.addEventListener('DOMContentLoaded', forceHideProductDropdown);
            window.addEventListener('load', forceHideProductDropdown);
        })();

        function repositionProductDropdown() {
            var list = document.getElementById('productDropdownList');
            var searchInput = document.getElementById('productSearch');
            if (!list || !searchInput) return;
            var rect = searchInput.getBoundingClientRect();
            var spaceBelow = window.innerHeight - rect.bottom - 8;
            var spaceAbove = rect.top - 8;
            var maxH;
            if (spaceBelow >= 160 || spaceBelow >= spaceAbove) {
                maxH = Math.min(220, Math.max(100, spaceBelow));
                list.style.top    = rect.bottom + 'px';
                list.style.bottom = 'auto';
                list.style.borderRadius = '0 0 8px 8px';
                list.style.borderTop    = 'none';
                list.style.borderBottom = '1.5px solid #e2e8f0';
            } else {
                maxH = Math.min(220, Math.max(100, spaceAbove));
                list.style.top    = 'auto';
                list.style.bottom = (window.innerHeight - rect.top) + 'px';
                list.style.borderRadius = '8px 8px 0 0';
                list.style.borderTop    = '1.5px solid #e2e8f0';
                list.style.borderBottom = 'none';
            }
            list.style.left     = rect.left + 'px';
            list.style.width    = rect.width + 'px';
            list.style.maxHeight = maxH + 'px';
        }

        function openProductDropdown() {
            var list = document.getElementById('productDropdownList');
            if (!list) return;
            // Ensure portal into body
            if (list.parentElement !== document.body) {
                document.body.appendChild(list);
                list.style.position = 'fixed';
            }
            list.style.zIndex = '9990';
            repositionProductDropdown();
            list.classList.add('is-open');
            list.style.display = 'block';
        }

        function closeProductDropdown() {
            var list = document.getElementById('productDropdownList');
            if (list) {
                list.classList.remove('is-open');
                list.style.display = 'none';
            }
        }

        function toggleProductDropdown() {
            var list = document.getElementById('productDropdownList');
            if (!list) return;
            if (!list.classList.contains('is-open')) {
                openProductDropdown();
                filterProductDropdown(false);
            } else {
                closeProductDropdown();
            }
        }

        // Reposition on scroll/resize so it follows the input
        window.addEventListener('scroll', function() {
            var list = document.getElementById('productDropdownList');
            if (list && list.style.display !== 'none') repositionProductDropdown();
        }, true);
        window.addEventListener('resize', function() {
            var list = document.getElementById('productDropdownList');
            if (list && list.style.display !== 'none') repositionProductDropdown();
        });

        function clearProductSearch() {
            const searchInput = document.getElementById('productSearch');
            if (searchInput) {
                searchInput.value = '';
                searchInput.focus();
                filterProductDropdown(true);
            }
        }

        function filterProductDropdown(shouldOpen = false) {
            const searchInput = document.getElementById('productSearch');
            const rawQ = (searchInput ? searchInput.value : '').trim().toLowerCase();
            const list = document.getElementById('productDropdownList');
            const clearBtn = document.getElementById('productClearBtn');
            if (clearBtn) {
                clearBtn.style.display = rawQ ? 'inline-block' : 'none';
            }
            if (!list) return;
            if (shouldOpen) {
                list.style.display = 'block';
            }
            
            // Smart multi-token keyword search (matches all words regardless of order)
            const terms = rawQ ? rawQ.split(/\s+/).filter(Boolean) : [];
            let totalVisible = 0;

            const options = list.querySelectorAll('.prod-option');
            options.forEach(opt => {
                const searchStr = (opt.getAttribute('data-search') || opt.dataset.search || opt.textContent || '').toLowerCase();
                const matches = terms.length === 0 || terms.every(t => searchStr.includes(t));
                if (matches) {
                    opt.classList.remove('is-hidden');
                    opt.style.setProperty('display', 'flex', 'important');
                    totalVisible++;
                } else {
                    opt.classList.add('is-hidden');
                    opt.style.setProperty('display', 'none', 'important');
                }
            });

            const headers = list.querySelectorAll('.prod-group-header');
            headers.forEach(hdr => {
                const group = hdr.getAttribute('data-group') || hdr.dataset.group || '';
                const hasVisible = Array.from(list.querySelectorAll(`.prod-option[data-cat="${group}"]`))
                    .some(o => !o.classList.contains('is-hidden') && o.style.display !== 'none');
                if (hasVisible) {
                    hdr.classList.remove('is-hidden');
                    hdr.style.setProperty('display', 'block', 'important');
                } else {
                    hdr.classList.add('is-hidden');
                    hdr.style.setProperty('display', 'none', 'important');
                }
            });

            // No products match feedback message
            let noMatch = document.getElementById('prodNoMatchMessage');
            if (!noMatch) {
                noMatch = document.createElement('div');
                noMatch.id = 'prodNoMatchMessage';
                noMatch.style.cssText = 'padding:16px;text-align:center;color:#64748b;font-size:12.5px;';
                list.appendChild(noMatch);
            }
            if (totalVisible === 0 && terms.length > 0) {
                const safeQ = rawQ.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
                noMatch.innerHTML = '<i class="fas fa-search" style="margin-right:6px;color:#94a3b8;"></i>No products found matching "<strong>' + safeQ + '</strong>"';
                noMatch.style.setProperty('display', 'block', 'important');
            } else {
                noMatch.style.setProperty('display', 'none', 'important');
            }
        }

        // ── Called when a product checkbox is toggled — auto-adds/removes cart item ──
        function onProductCheckboxChange(cb) {
            const pid   = String(cb.dataset.id);
            const name  = cb.dataset.name;
            const price = parseFloat(cb.dataset.price) || 0;
            const stock = parseInt(cb.dataset.stock) || 0;
            const unit  = cb.dataset.unit || 'Piece (pc)';
            const cat   = cb.dataset.cat || '';
            const size  = cb.dataset.size || '';

            if (cb.checked) {
                // Guard stock
                if (stock <= 0) {
                    showTxnAlert('This product is out of stock.', 'warning');
                    cb.checked = false;
                    return;
                }
                // Use the quantity field value (default 1)
                const qtyInput = document.getElementById('itemQty');
                const qtyVal = Math.max(1, parseInt(qtyInput ? qtyInput.value : 1) || 1);
                if (qtyVal > stock) {
                    showTxnAlert('Insufficient stock. Available: ' + stock, 'warning');
                    cb.checked = false;
                    return;
                }
                const existing = cart.find(i => i.item_type === 'merchandise' && String(i.product_id) === pid);
                if (!existing) {
                    cart.push({
                        item_type:    'merchandise',
                        product_id:   pid,
                        product_name: name,
                        category:     cat,
                        size_variant: size,
                        quantity:     qtyVal,
                        unit_price:   price,
                        unit:         unit,
                    });
                } else {
                    // Already in cart — update quantity to match field
                    existing.quantity = qtyVal;
                }
            } else {
                // Remove from cart
                cart = cart.filter(i => !(i.item_type === 'merchandise' && String(i.product_id) === pid));
            }

            // Also fill in the form fields for reference
            selectedProduct = cb.checked ? {
                id: pid, name, sku: cb.dataset.sku, cat, size, price, stock, unit
            } : null;
            if (cb.checked) {
                const qtyEl = document.getElementById('itemQty');
                if (qtyEl && !qtyEl.value) qtyEl.value = 1;
                const search = document.getElementById('productSearch');
                if (search) search.value = name + (size ? ' · ' + size : '');
                const skuEl   = document.getElementById('itemSku');
                const catEl   = document.getElementById('itemCategory');
                const priceEl = document.getElementById('itemUnitPrice');
                const stockEl = document.getElementById('itemStock');
                if (skuEl)   skuEl.value   = cb.dataset.sku || '—';
                if (catEl)   catEl.value   = cat || '—';
                if (priceEl) priceEl.value = price.toFixed(2);
                if (stockEl) {
                    stockEl.value = stock > 0 ? stock + ' available' : 'Out of stock';
                    stockEl.style.color = stock > 0 ? '#065f46' : '#dc2626';
                }
            }

            renderCart();
            updateCheckoutBtn();
            closeProductDropdown();
        }

        // ── Sync checkbox states to match cart (called after cart changes) ───
        function syncProductCheckboxes() {
            document.querySelectorAll('.merch-prod-checkbox').forEach(cb => {
                const pid = String(cb.dataset.id);
                const inCart = cart.some(i => i.item_type === 'merchandise' && String(i.product_id) === pid);
                cb.checked = inCart;
            });
        }

        function selectProduct(el) {
            // When clicking the label area (not the checkbox itself), toggle the checkbox
            const cb = el.querySelector ? el.querySelector('.merch-prod-checkbox') : null;
            if (cb && !cb.disabled) {
                cb.checked = !cb.checked;
                onProductCheckboxChange(cb);
                return;
            }
            // Fallback: old behavior for direct element calls
            selectedProduct = {
                id:    el.dataset.id,
                name:  el.dataset.name,
                sku:   el.dataset.sku,
                cat:   el.dataset.cat,
                size:  el.dataset.size,
                price: parseFloat(el.dataset.price) || 0,
                stock: parseInt(el.dataset.stock) || 0,
                unit:  el.dataset.unit || 'Piece (pc)',
            };
            const qtyInput = document.getElementById('itemQty');
            if (qtyInput && !qtyInput.value) qtyInput.value = 1;
            const search = document.getElementById('productSearch');
            if (search) search.value = selectedProduct.name + (selectedProduct.size ? ' · ' + selectedProduct.size : '');
            const sku   = document.getElementById('itemSku');
            const cat   = document.getElementById('itemCategory');
            const price = document.getElementById('itemUnitPrice');
            const stock = document.getElementById('itemStock');
            if (sku)   sku.value   = selectedProduct.sku || '—';
            if (cat)   cat.value   = selectedProduct.cat || '—';
            if (price) price.value = selectedProduct.price.toFixed(2);
            let rawUnit = (selectedProduct.unit || 'pc').toLowerCase();
            let uomLabel = 'pcs';
            if (rawUnit.includes('bottle')) uomLabel = 'Bottles';
            else if (rawUnit.includes('liter') || rawUnit.includes('litre')) uomLabel = 'Liters';
            else if (rawUnit.includes('can')) uomLabel = 'Cans';
            else if (rawUnit.includes('box')) uomLabel = 'Boxes';
            else if (rawUnit.includes('set')) uomLabel = 'Sets';
            else if (rawUnit.includes('pack')) uomLabel = 'Packs';
            else if (rawUnit.includes('pair')) uomLabel = 'Pairs';
            else if (rawUnit.includes('pc') || rawUnit.includes('piece')) uomLabel = 'pcs';
            else uomLabel = selectedProduct.unit || 'pcs';
            if (stock) {
                if (selectedProduct.stock > 0) {
                    stock.value = selectedProduct.stock + ' ' + uomLabel + ' available';
                    stock.style.color = '#065f46';
                } else {
                    stock.value = 'Out of stock (0 ' + uomLabel + ')';
                    stock.style.color = '#dc2626';
                }
            }
            closeProductDropdown();
        }

        // Close dropdown when clicking outside or clicking any modal trigger
        document.addEventListener('click', function(e) {
            const wrap = document.getElementById('productDropdownWrap');
            const isAddBtn = e.target.closest('button[onclick*="openAddProductModal"]') || e.target.closest('button[onclick*="openAdd"]');
            if (isAddBtn || (wrap && !wrap.contains(e.target))) {
                closeProductDropdown();
            }
        });

        // Keyboard navigation for product search
        document.addEventListener('DOMContentLoaded', function() {
            const pSearch = document.getElementById('productSearch');
            if (pSearch) {
                pSearch.addEventListener('keydown', function(e) {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        const list = document.getElementById('productDropdownList');
                        if (!list) return;
                        // Find first visible in-stock option
                        const visibleOptions = Array.from(list.querySelectorAll('.prod-option')).filter(o => o.style.display !== 'none');
                        if (visibleOptions.length > 0) {
                            const cb = visibleOptions[0].querySelector('.merch-prod-checkbox:not(:disabled)');
                            if (cb) {
                                cb.checked = !cb.checked;
                                onProductCheckboxChange(cb);
                            }
                        }
                    } else if (e.key === 'Escape') {
                        closeProductDropdown();
                    }
                });
            }
        });

        // ── Mechanic busy-status check ────────────────────────────────────────
        // Fires when the Assigned Mechanic dropdown changes.
        // Calls the API and shows a warning banner if the mechanic has ongoing jobs.
        // ── Mechanic Typeahead Dropdown ──────────────────────────────────────
        function filterMechanicDropdown(query) {
            const dd    = document.getElementById('joMechanicDropdown');
            const items = dd ? dd.querySelectorAll('.jo-mechanic-item') : [];
            const q     = query.toLowerCase().trim();
            let anyVisible = false;
            items.forEach(item => {
                const name = (item.dataset.name || '').toLowerCase();
                const spec = (item.dataset.spec || '').toLowerCase();
                const show = !q || name.includes(q) || spec.includes(q);
                item.style.display = show ? '' : 'none';
                if (show) anyVisible = true;
            });
            if (dd) dd.style.display = 'block';
            // Clear hidden fields if text was manually changed (no selection yet)
            const hiddenId = document.getElementById('joMechanicId');
            if (hiddenId && hiddenId.value) {
                // User is typing again — deselect previous choice
                hiddenId.value = '';
                document.getElementById('joMechanicName').value = '';
            }
        }

        function showMechanicDropdown() {
            const dd    = document.getElementById('joMechanicDropdown');
            const items = dd ? dd.querySelectorAll('.jo-mechanic-item') : [];
            items.forEach(i => i.style.display = '');   // show all
            if (dd) dd.style.display = 'block';
        }

        window.hideMechanicDropdown = function hideMechanicDropdown() {
            const dd = document.getElementById('joMechanicDropdown');
            if (dd) dd.style.display = 'none';
        }

        function selectMechanic(el) {
            const id   = el.dataset.id   || '';
            const name = el.dataset.name || '';
            document.getElementById('joMechanic').value     = name;
            document.getElementById('joMechanicId').value   = id;
            document.getElementById('joMechanicName').value = name;
            hideMechanicDropdown();
            // Trigger busy-check
            onMechanicChange();
        }

        // ── Mechanic Busy-Check ──────────────────────────────────────────────
        async function onMechanicChange() {
            const warnBox = document.getElementById('joMechanicBusyWarn');
            const listEl  = document.getElementById('joMechanicBusyList');
            if (!warnBox || !listEl) return;

            // Now reads from the hidden ID field (joMechanic is a text input)
            const mechId = (document.getElementById('joMechanicId')?.value || '').trim();
            if (!mechId) {
                warnBox.style.display = 'none';
                listEl.innerHTML = '';
                return;
            }

            try {
                const res  = await fetch(`../backend/api/get_mechanic_status.php?mechanic_id=${encodeURIComponent(mechId)}`, {
                    credentials: 'same-origin',
                });
                const data = await res.json();

                if (data.busy && data.jobs && data.jobs.length > 0) {
                    const statusColors = {
                        'In Progress':        '#1e40af',
                        'Pending':            '#92400e',
                        'Pending Validation': '#92400e',
                        'Approved':           '#065f46',
                        'Validated':          '#065f46',
                    };
                    listEl.innerHTML = data.jobs.map(j => {
                        const color  = statusColors[j.status] || '#475569';
                        const plate  = j.vehicle_plate ? ` — <strong>${j.vehicle_plate}</strong>` : '';
                        const svc    = j.service_label  ? ` (${j.service_label})`                 : '';
                        const ref    = j.jo_ref         ? `<span style="font-weight:700;">${j.jo_ref}</span>` : '';
                        return `<div style="display:flex;align-items:center;gap:6px;padding:4px 8px;
                                            background:#fff;border:1px solid #fde68a;border-radius:6px;font-size:11px;">
                                    <span style="width:8px;height:8px;border-radius:50%;background:${color};flex-shrink:0;"></span>
                                    ${ref}${svc}${plate}
                                    <span style="margin-left:auto;color:${color};font-weight:700;">${j.status}</span>
                                </div>`;
                    }).join('');
                    warnBox.style.display = 'block';
                } else {
                    warnBox.style.display = 'none';
                    listEl.innerHTML = '';
                }
            } catch (err) {
                // Silently ignore network errors — don't block the workflow
                warnBox.style.display = 'none';
            }
        }

        // Helper: get category for a service type object.
        // Prefers the DB-sourced `category` field (now always present in API response).
        // Falls back to name/key inference for typed custom values not yet in DB.
        function getServiceCategory(svc) {
            if (!svc) return 'Others';
            // Primary: use DB-stored category if present
            if (svc.category) return svc.category;
            // Fallback inference for un-saved / custom names
            const key  = svc.key  || '';
            const name = (svc.name || '').toLowerCase();
            if (name.includes('oil') || name.includes('lube') || name.includes('grease') || name.includes('flush'))  return 'Lubrication';
            if (name.includes('pms') || name.includes('preventive') || name.includes('km'))                            return 'PMS';
            if (name.includes('spark') || name.includes('glow') || name.includes('throttle') || name.includes('carbon') || name.includes('timing belt') || name.includes('serpentine') || name.includes('valve cover') || name.includes('compression') || name.includes('intake') || name.includes('injector clean')) return 'Engine';
            if (name.includes('fuel pump') || name.includes('fuel tank') || name.includes('fuel line') || name.includes('fuel inject') || name.includes('diesel injector') || name.includes('fuel pressure') || name.includes('fuel rail')) return 'Fuel System';
            if (name.includes('radiator') || name.includes('coolant') || name.includes('thermostat') || name.includes('water pump') || name.includes('cooling'))                                                                              return 'Cooling System';
            if (name.includes('atf') || name.includes('cvt') || name.includes('transmission') || name.includes('clutch') || name.includes('differential') || name.includes('transfer case') || name.includes('gear oil'))                    return 'Transmission';
            if (name.includes('brake'))                                                                                 return 'Brake';
            if (name.includes('shock') || name.includes('coil spring') || name.includes('ball joint') || name.includes('stabilizer') || name.includes('control arm') || name.includes('rack end') || name.includes('tie rod'))             return 'Suspension';
            if (name.includes('steering') || name.includes('wheel bearing'))                                           return 'Steering';
            if (name.includes('tire') || name.includes('wheel align') || name.includes('wheel balanc') || name.includes('vulcan') || name.includes('mounting'))                                                                              return 'Tire Services';
            if (name.includes('battery') || name.includes('alternator') || name.includes('starter motor'))            return 'Battery Services';
            if (name.includes('headlight') || name.includes('taillight') || name.includes('bulb') || name.includes('fuse') || name.includes('wiring'))                                                                                       return 'Electrical';
            if (name.includes('aircon') || name.includes('air conditioning') || name.includes('a/c') || name.includes('refrigerant')) return 'Air Conditioning';
            if (name.includes('ecu') || name.includes('obd') || name.includes('diagnostic') || name.includes('scan')) return 'Diagnostics';
            if (name.includes('inspection') || name.includes('safety check') || name.includes('lto'))                 return 'Inspection';
            return 'Others';
        }

        // ── JO Service type change ────────────────────────────────────────────
        // When a service type is selected:
        //   1. Auto-fill the service fee from cached data
        //   2. Show pricing notes
        //   3. Fetch suggested parts from DB and preview them
        // Helper: sync category dropdown selection case-insensitively
        function syncServiceCategory(cat) {
            const categorySelect = document.getElementById('joServiceCategory');
            if (!categorySelect || !cat) return;
            const target = String(cat).toLowerCase().trim();
            let found = false;
            for (let i = 0; i < categorySelect.options.length; i++) {
                const optVal = categorySelect.options[i].value.toLowerCase().trim();
                const optTxt = categorySelect.options[i].text.toLowerCase().trim();
                if (optVal === target || optTxt === target) {
                    categorySelect.selectedIndex = i;
                    found = true;
                    break;
                }
            }
            if (!found) {
                for (let i = 0; i < categorySelect.options.length; i++) {
                    if (categorySelect.options[i].value === 'Others') {
                        categorySelect.selectedIndex = i;
                        break;
                    }
                }
            }
        }

        // ── JO Service type change ────────────────────────────────────────────
        function onJoServiceTypeChange() {
            const input      = document.getElementById('joServiceType');
            const hidden     = document.getElementById('joServiceTypeValue');
            const notesWrap  = document.getElementById('joServicePriceNotes');
            const notesText  = document.getElementById('joServicePriceNotesText');
            const priceInput = document.getElementById('joServicePrice');
            const autoInfo   = document.getElementById('joServiceAutoInfo');
            const autoCategory = document.getElementById('joServiceAutoCategory');
            const autoPrice    = document.getElementById('joServiceAutoPrice');
            const autoDuration = document.getElementById('joServiceAutoDuration');
            if (!hidden) return;
            
            const val = hidden.value || (input ? input.value : '');

            const svc = (window.JO_SERVICE_TYPES || []).find(s => s.name.toLowerCase() === val.toLowerCase());
            if (svc) {
                if (hidden && hidden.value !== svc.name) hidden.value = svc.name;
                if (input && input.value !== svc.name) input.value = svc.name;
                
                if (priceInput) {
                    priceInput.value = svc.price > 0 ? svc.price.toFixed(2) : '';
                }
                if (notesWrap && notesText && svc.notes) {
                    notesText.textContent = svc.notes;
                    notesWrap.style.display = 'block';
                } else if (notesWrap) {
                    notesWrap.style.display = 'none';
                }
                
                // Auto-fetch category
                const computedCat = getServiceCategory(svc);
                syncServiceCategory(computedCat);

                // Populate the visible auto-info panel (Category only)
                if (autoInfo) {
                    if (autoCategory) autoCategory.textContent = computedCat || '—';
                    autoInfo.style.display = 'block';
                }

                // Pre-fill the visible Service Price editable field
                if (priceInput) {
                    priceInput.value = svc.price > 0 ? svc.price.toFixed(2) : '';
                }

                if (svc.key) fetchServiceParts(svc.key);
            } else {
                if (notesWrap) notesWrap.style.display = 'none';
                if (autoInfo) autoInfo.style.display = 'none';
                if (val) {
                    const computedCat = getServiceCategory({ name: val });
                    syncServiceCategory(computedCat);
                }
                clearSuggestedParts();
            }
        }

        // ── Filter service types dropdown ─────────────────────────────────────
        // ── Filter service types dropdown ─────────────────────────────────────
        function getSelectedServiceNames() {
            return cart
                .filter(i => i.item_type === 'service' && i.category !== 'Labor' && i.category !== 'Tip' && i.product_name !== 'Labor Charge' && i.product_name !== 'Tip')
                .map(i => i.product_name);
        }

        function syncServiceCheckboxes() {
            const selectedNames = getSelectedServiceNames();
            document.querySelectorAll('.jo-svc-checkbox').forEach(cb => {
                cb.checked = selectedNames.includes(cb.value);
            });
        }

        function onServiceCheckboxChange(cb) {
            const name = cb.value;
            const isChecked = cb.checked;
            const types = window.JO_SERVICE_TYPES || [];
            const svc = types.find(s => s.name === name);
            const price = (svc && parseFloat(svc.price) > 0) ? parseFloat(svc.price) : (parseFloat(cb.dataset.price) || 0);

            if (isChecked) {
                const existing = cart.find(i => i.item_type === 'service' && i.product_name === name);
                if (!existing) {
                    cart.push({
                        item_type:    'service',
                        product_name: name,
                        category:     svc ? getServiceCategory(svc) : (cb.dataset.category || 'Service Fee'),
                        size_variant: '',
                        product_id:   null,
                        quantity:     1,
                        unit_price:   price,
                    });
                }
            } else {
                cart = cart.filter(i => !(i.item_type === 'service' && i.product_name === name));
            }

            updateServiceSelectionState();
            hideServiceDropdown();
        }

        function updateServiceSelectionState() {
            const selectedNames = getSelectedServiceNames();
            const hidden = document.getElementById('joServiceTypeValue');
            if (hidden) hidden.value = selectedNames.join(', ');

            // Update tags display if present
            const tagsDiv = document.getElementById('joSelectedServicesTags');
            if (tagsDiv) {
                if (selectedNames.length > 0) {
                    tagsDiv.style.display = 'flex';
                    tagsDiv.innerHTML = selectedNames.map(name => {
                        return `<span style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:20px;padding:3px 10px;font-size:11px;color:#1e40af;font-weight:600;display:inline-flex;align-items:center;gap:5px;">
                                    ${escapeHtml(name)}
                                    <span onclick="removeServiceByName('${escapeHtml(name.replace(/'/g,"\\'"))}')" style="cursor:pointer;color:#64748b;font-size:13px;line-height:1;">&times;</span>
                                </span>`;
                    }).join('');
                } else {
                    tagsDiv.style.display = 'none';
                    tagsDiv.innerHTML = '';
                }
            }

            const types = window.JO_SERVICE_TYPES || [];
            let totalPrice = 0;

            selectedNames.forEach(name => {
                const item = cart.find(i => i.item_type === 'service' && i.product_name === name);
                if (item) totalPrice += (item.unit_price * item.quantity);

                const svc = types.find(s => s.name === name);
                if (svc && svc.key && selectedNames.length === 1) {
                    fetchServiceParts(svc.key);
                }
            });

            const priceInput = document.getElementById('joServicePrice');
            if (priceInput) priceInput.value = totalPrice > 0 ? totalPrice.toFixed(2) : '';

            // Sync category
            if (selectedNames.length > 0) {
                const firstSvc = types.find(s => s.name === selectedNames[0]);
                if (firstSvc) {
                    const cat = getServiceCategory(firstSvc);
                    syncServiceCategory(cat);
                    const autoCategory = document.getElementById('joServiceAutoCategory');
                    if (autoCategory) autoCategory.textContent = cat;
                }
            } else {
                syncServiceCategory('');
            }

            syncServiceCheckboxes();
            renderCart();
            updateCheckoutBtn();
        }

        function removeServiceByName(name) {
            cart = cart.filter(i => !(i.item_type === 'service' && i.product_name === name));
            updateServiceSelectionState();
            hideServiceDropdown();
        }

        function filterServiceTypes(shouldOpen = false) {
            const input = document.getElementById('joServiceType');
            const list = document.getElementById('joServiceTypeList');
            const dropdown = document.getElementById('joServiceTypeDropdown');
            
            if (!input || !list) return;
            
            const filter = input.value.toLowerCase().trim();
            const types = window.JO_SERVICE_TYPES || [];
            const filtered = filter ? types.filter(t => t.name.toLowerCase().includes(filter)) : types;
            
            if (filtered.length === 0) {
                list.innerHTML = '<div style="padding:10px;color:#94a3b8;font-size:13px;text-align:center;">No services found</div>';
            } else {
                const selectedNames = getSelectedServiceNames();
                const groups = {};
                filtered.forEach(t => {
                    const cat = getServiceCategory(t) || 'Others';
                    if (!groups[cat]) groups[cat] = [];
                    groups[cat].push(t);
                });

                let html = '';
                Object.keys(groups).sort().forEach(cat => {
                    html += `<div style="padding:6px 12px 3px;font-size:10px;font-weight:700;color:#64748b;text-transform:uppercase;letter-spacing:.5px;background:#f8fafc;border-bottom:1px solid #f1f5f9;">${escapeHtml(cat)}</div>`;
                    groups[cat].forEach(t => {
                        const isChecked = selectedNames.includes(t.name) ? 'checked' : '';
                        html += `
                            <label style="display:flex;align-items:center;gap:10px;padding:8px 12px;cursor:pointer;border-bottom:1px solid #f1f5f9;font-size:13px;color:#1e293b;transition:background 0.15s;"
                                   onmouseover="this.style.background='#f0f7ff'" onmouseout="this.style.background=''">
                                <input type="checkbox"
                                       class="jo-svc-checkbox"
                                       value="${escapeHtml(t.name)}"
                                       data-price="${parseFloat(t.price)||0}"
                                       data-category="${escapeHtml(cat)}"
                                       ${isChecked}
                                       onchange="onServiceCheckboxChange(this)"
                                       style="width:18px !important;height:18px !important;min-width:18px !important;max-width:18px !important;flex-shrink:0 !important;display:inline-block !important;margin:0 10px 0 0 !important;accent-color:#002F70;cursor:pointer;">
                                <span style="flex:1;">${escapeHtml(t.name)}</span>
                            </label>`;
                    });
                });
                list.innerHTML = html;
            }
            
            if (dropdown && (shouldOpen || document.activeElement === input)) {
                dropdown.style.display = 'block';
            }
        }
        
        // ── Show service dropdown ─────────────────────────────────────────────
        function showServiceDropdown() {
            const dropdown = document.getElementById('joServiceTypeDropdown');
            const input = document.getElementById('joServiceType');
            if (!dropdown || !input) return;
            filterServiceTypes(true);
            dropdown.style.display = 'block';
        }
        
        // ── Hide service dropdown ─────────────────────────────────────────────
        function hideServiceDropdown() {
            const dropdown = document.getElementById('joServiceTypeDropdown');
            if (dropdown) dropdown.style.display = 'none';
        }

        // Close dropdowns when clicking outside
        document.addEventListener('click', function(e) {
            const pWrap = document.getElementById('productDropdownWrap');
            if (pWrap && !pWrap.contains(e.target)) {
                closeProductDropdown();
            }

            const input    = document.getElementById('joServiceType');
            const dropdown = document.getElementById('joServiceTypeDropdown');
            if (input && dropdown &&
                !input.contains(e.target) &&
                !dropdown.contains(e.target)) {
                hideServiceDropdown();
            }
        });

        // Ensure dropdowns are strictly hidden on page load / refresh
        document.addEventListener('DOMContentLoaded', function() {
            closeProductDropdown();
            hideServiceDropdown();
        });
        window.addEventListener('load', function() {
            closeProductDropdown();
            hideServiceDropdown();
        });
        
        // ── Select service type ───────────────────────────────────────────────
        function selectServiceType(serviceName) {
            const cb = document.querySelector(`.jo-svc-checkbox[value="${CSS.escape(serviceName)}"]`);
            if (cb) {
                cb.checked = !cb.checked;
                onServiceCheckboxChange(cb);
            } else {
                const selectedNames = getSelectedServiceNames();
                if (selectedNames.includes(serviceName)) {
                    cart = cart.filter(i => !(i.item_type === 'service' && i.product_name === serviceName));
                } else {
                    const types = window.JO_SERVICE_TYPES || [];
                    const svc = types.find(s => s.name === serviceName);
                    const price = svc && parseFloat(svc.price) > 0 ? parseFloat(svc.price) : 0;
                    cart.push({
                        item_type:    'service',
                        product_name: serviceName,
                        category:     svc ? getServiceCategory(svc) : 'Service Fee',
                        size_variant: '',
                        product_id:   null,
                        quantity:     1,
                        unit_price:   price,
                    });
                }
                updateServiceSelectionState();
                hideServiceDropdown();
            }
        }

        // ── Fetch suggested parts from DB ─────────────────────────────────────
        async function fetchServiceParts(serviceKey) {
            const partsWrap = document.getElementById('joSuggestedParts');
            const partsList = document.getElementById('joSuggestedPartsList');
            const indicator = document.getElementById('joPartsLoadingIndicator');

            if (!partsWrap || !partsList) return;

            // Show loading
            if (indicator) indicator.style.display = 'flex';
            partsWrap.style.display = 'none';

            try {
                const res  = await fetch(`../backend/api/get_service_parts.php?service_key=${encodeURIComponent(serviceKey)}`, {
                    credentials: 'same-origin'
                });
                const data = await res.json();

                if (indicator) indicator.style.display = 'none';

                if (!data.success || !data.parts || data.parts.length === 0) {
                    partsWrap.style.display = 'none';
                    window._joSuggestedParts = [];
                    return;
                }

                // Cache parts for use in applyJobOrderToCart
                window._joSuggestedParts = data.parts;

                // Render preview
                partsList.innerHTML = data.parts.map(p => {
                    const stockBadge = p.in_stock
                        ? `<span style="background:#f0fdf4;color:#166534;border:1px solid #86efac;padding:1px 6px;border-radius:10px;font-size:10px;font-weight:600;">In Stock (${p.stock_level})</span>`
                        : `<span style="background:#fee2e2;color:#991b1b;border:1px solid #fca5a5;padding:1px 6px;border-radius:10px;font-size:10px;font-weight:600;">Out of Stock</span>`;
                    const reqBadge = p.is_required
                        ? `<span style="background:#fffbeb;color:#92400e;border:1px solid #fde68a;padding:1px 6px;border-radius:10px;font-size:10px;font-weight:600;">Required</span>`
                        : '';
                    const price = p.unit_price > 0 ? ` · ₱${fmtNum(p.unit_price)}` : '';
                    return `<div style="display:flex;align-items:center;gap:6px;padding:5px 0;border-bottom:1px solid #fde68a;flex-wrap:wrap;">
                        <i class="fas fa-box" style="color:#b45309;font-size:10px;flex-shrink:0;"></i>
                        <span style="font-weight:600;color:#1e293b;">${escHtml(p.product_name)}</span>
                        <span style="color:#64748b;">×${p.default_quantity}${price}</span>
                        ${reqBadge}
                        ${stockBadge}
                    </div>`;
                }).join('');

                partsWrap.style.display = 'block';

            } catch (err) {
                if (indicator) indicator.style.display = 'none';
                partsWrap.style.display = 'none';
                window._joSuggestedParts = [];
                console.warn('fetchServiceParts error:', err);
            }
        }

        function clearSuggestedParts() {
            window._joSuggestedParts = [];
            const partsWrap = document.getElementById('joSuggestedParts');
            if (partsWrap) partsWrap.style.display = 'none';
        }

        // ── Apply Job Order to Cart (service fee + auto-parts) ────────────────
        // This is the single entry point for adding a JO service to the cart.
        // It adds:
        //   1. The service fee as a 'service' line item
        //   2. All suggested parts (from DB) as 'merchandise' line items
        //      — skips parts that are out of stock (warns user)
        //      — skips parts already in cart (merges quantity)
        async function applyJobOrderToCart() {
            const svcType     = (document.getElementById('joServiceTypeValue')?.value || document.getElementById('joServiceType')?.value || '').trim();
            const laborCharge = parseFloat((document.getElementById('joLaborCharge')?.value || '0').replace(/[^0-9.]/g, '')) || 0;
            const enteredPrice = parseFloat((document.getElementById('joServicePrice')?.value || '0').replace(/[^0-9.]/g, '')) || 0;

            if (!svcType) return; // caller already validated

            const selectedNames = svcType.split(', ').map(s => s.trim()).filter(Boolean);
            const types = window.JO_SERVICE_TYPES || [];

            // ── 1. Ensure each selected service is in cart individually ──────────
            selectedNames.forEach(name => {
                const svc = types.find(s => s.name === name);
                let price = svc && parseFloat(svc.price) > 0 ? parseFloat(svc.price) : 0;
                if (enteredPrice > 0 && (selectedNames.length === 1 || price <= 0)) {
                    price = enteredPrice;
                }
                const existing = cart.find(i => i.item_type === 'service' && i.product_name === name);
                if (existing) {
                    if (price > 0) existing.unit_price = price;
                } else {
                    cart.push({
                        item_type:    'service',
                        product_name: name,
                        category:     svc ? getServiceCategory(svc) : 'Service Fee',
                        size_variant: '',
                        product_id:   null,
                        quantity:     1,
                        unit_price:   price,
                    });
                }
            });

            // ── 1b. Add tip as separate line item (if > 0) ───────────────────
            if (laborCharge > 0) {
                const laborLabel = 'Tip';
                const existingLabor = cart.find(i => i.item_type === 'service' && (i.product_name === laborLabel || i.product_name === 'Labor Charge' || i.category === 'Labor' || i.category === 'Tip'));
                if (existingLabor) {
                    existingLabor.product_name = laborLabel;
                    existingLabor.category = 'Tip';
                    existingLabor.unit_price = laborCharge;
                } else {
                    cart.push({
                        item_type:    'service',
                        product_name: laborLabel,
                        category:     'Tip',
                        size_variant: '',
                        product_id:   null,
                        quantity:     1,
                        unit_price:   laborCharge,
                    });
                }
            } else {
                cart = cart.filter(i => i.category !== 'Labor' && i.category !== 'Tip' && i.product_name !== 'Labor Charge' && i.product_name !== 'Tip');
            }

            // ── 2. Add suggested parts as merchandise items ───────────────────
            const parts = window._joSuggestedParts || [];
            const skipped = [];

            for (const part of parts) {
                if (!part.product_id) {
                    // Part not found in inventory — skip silently
                    continue;
                }
                if (!part.in_stock) {
                    skipped.push(part.product_name);
                    continue;
                }

                const qty = part.default_quantity || 1;
                const existing = cart.find(i =>
                    i.item_type === 'merchandise' && i.product_id == part.product_id
                );

                if (existing) {
                    // Merge — respect stock ceiling
                    const newQty = existing.quantity + qty;
                    existing.quantity = Math.min(newQty, part.stock_level);
                } else {
                    cart.push({
                        item_type:    'merchandise',
                        product_id:   part.product_id,
                        product_name: part.product_name,
                        category:     part.category,
                        size_variant: part.size || '',
                        quantity:     Math.min(qty, part.stock_level),
                        unit_price:   part.unit_price,
                    });
                }
            }

            renderCart();
            updateCheckoutBtn();
            if (typeof calcLoyaltyPoints === 'function') calcLoyaltyPoints();

            // ── 3. Feedback ───────────────────────────────────────────────────
            if (skipped.length > 0) {
                showTxnAlert(
                    `Service added. ${skipped.length} part(s) skipped (out of stock): ${skipped.join(', ')}`,
                    'warning'
                );
            } else if (parts.length > 0) {
                showTxnAlert(
                    `"${selectedNames.join(', ')}" + ${parts.filter(p => p.product_id && p.in_stock).length} part(s) added to cart.`,
                    'success'
                );
            } else {
                showTxnAlert(`"${selectedNames.join(', ')}" added to cart.`, 'success');
            }
        }

        // ── Load service types from database ──────────────────────────────────
        async function loadServiceTypes(selectValue) {
            const input = document.getElementById('joServiceType');
            const hidden = document.getElementById('joServiceTypeValue');
            if (!input || !hidden) return;
            try {
                const res  = await fetch('../backend/api/get_service_types.php', { credentials: 'same-origin' });
                const data = await res.json();
                if (!data.success) throw new Error(data.error || 'Failed to load service types');

                // Inline seed from PHP so services are available 0ms at page load
        if (!window.JO_SERVICE_TYPES || !window.JO_SERVICE_TYPES.length) {
            window.JO_SERVICE_TYPES = null || [];
        }

        // Cache for price/notes lookup and filtering
                if (data.success && Array.isArray(data.types) && data.types.length > 0) {
                    window.JO_SERVICE_TYPES = data.types;
                }

                // Set placeholder
                input.placeholder = 'Type to search service...';
                
                // If there's a pre-selected value, set it
                if (selectValue !== undefined) {
                    input.value = selectValue;
                    hidden.value = selectValue;
                    onJoServiceTypeChange();
                }

            } catch (err) {
                input.placeholder = '— Could not load service types —';
                console.error('loadServiceTypes error:', err);
            }
        }

        // ── Add Service Type modal ────────────────────────────────────────────
        function openAddServiceModal() {
            closeProductDropdown();
            if (typeof hideVehicleDropdown === 'function') hideVehicleDropdown();
            const nameEl  = document.getElementById('newServiceName');
            const priceEl = document.getElementById('newServicePrice');
            const catEl   = document.getElementById('newServiceCategory');
            const durationEl = document.getElementById('newServiceDuration');
            const descEl  = document.getElementById('newServiceDescription');
            const reasonEl = document.getElementById('newServiceReason');
            
            if (nameEl)  nameEl.value  = '';
            if (priceEl) priceEl.value = '';
            if (catEl)   catEl.value   = 'Others';
            if (durationEl) durationEl.value = '';
            if (descEl)  descEl.value  = '';
            if (reasonEl) reasonEl.value = '';
            setAddServiceError('');
            
            // Auto-detect category as they type in the modal
            if (nameEl && !nameEl.dataset.catListenerAdded) {
                nameEl.dataset.catListenerAdded = 'true';
                nameEl.addEventListener('input', function() {
                    if (catEl) {
                        catEl.value = getServiceCategory({ name: this.value });
                    }
                });
            }

            const modal = document.getElementById('addServiceModal');
            if (modal) modal.style.display = 'flex';
            setTimeout(() => nameEl && nameEl.focus(), 80);
        }

        function closeAddServiceModal() {
            const modal = document.getElementById('addServiceModal');
            if (modal) modal.style.display = 'none';
        }

        window.resetServiceInputValidation = function(el) {
            if (!el) return;
            el.style.borderColor = '';
            el.style.boxShadow = '';
            const box = document.getElementById('addServiceError');
            if (box) box.style.display = 'none';
        };

        function setAddServiceError(msg) {
            const box  = document.getElementById('addServiceError');
            const text = document.getElementById('addServiceErrorText');
            if (!box || !text) return;
            text.textContent = msg;
            box.style.display = msg ? 'flex' : 'none';
        }

        function highlightServiceError(fieldId, msg) {
            const fields = ['newServiceName', 'newServiceCategory', 'newServicePrice', 'newServiceDuration', 'newServiceDescription', 'newServiceReason'];
            fields.forEach(id => {
                const el = document.getElementById(id);
                if (el) {
                    el.style.borderColor = '';
                    el.style.boxShadow = '';
                }
            });
            const target = document.getElementById(fieldId);
            if (target) {
                target.style.setProperty('border-color', '#dc2626', 'important');
                target.style.setProperty('box-shadow', '0 0 0 3px rgba(220, 38, 38, 0.2)', 'important');
                target.focus();
            }
            setAddServiceError(msg);
        }

        async function submitNewServiceType() {
            const name     = (document.getElementById('newServiceName')?.value        || '').trim();
            const price    = (document.getElementById('newServicePrice')?.value       || '').trim();
            const category = (document.getElementById('newServiceCategory')?.value    || 'Others').trim();
            const duration = (document.getElementById('newServiceDuration')?.value    || '').trim();
            const description = (document.getElementById('newServiceDescription')?.value || '').trim();
            const reason   = (document.getElementById('newServiceReason')?.value      || '').trim();
            const btn      = document.getElementById('addServiceSubmitBtn');

            setAddServiceError('');

            if (!name || name.length < 3) {
                highlightServiceError('newServiceName', 'Please enter a valid Service Name (minimum 3 characters).');
                return;
            }
            if (name.length > 100) {
                highlightServiceError('newServiceName', 'Name is too long (maximum 100 characters).');
                return;
            }
            if (!category) {
                highlightServiceError('newServiceCategory', 'Please select a Category.');
                return;
            }
            if (price === '' || isNaN(price) || parseFloat(price) < 0) {
                highlightServiceError('newServicePrice', 'Please enter a valid Default Service Fee (₱0.00 or higher).');
                return;
            }
            if (!reason || reason.length < 5) {
                highlightServiceError('newServiceReason', 'Please provide a detailed reason for request (minimum 5 characters).');
                return;
            }

            if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Submitting…'; }

            try {
                const csrfMeta = document.querySelector('meta[name="csrf-token"]');
                const csrfToken = csrfMeta ? csrfMeta.getAttribute('content') : '';

                const res  = await fetch('../backend/api/submit_master_data_request.php', {
                    method: 'POST',
                    headers: { 
                        'Content-Type': 'application/json',
                        'X-CSRF-Token': csrfToken
                    },
                    credentials: 'same-origin',
                    body: JSON.stringify({
                        request_type: 'service_type',
                        request_data: {
                            service_name: name,
                            service_category: category,
                            default_price: parseFloat(price),
                            estimated_duration: duration,
                            description: description
                        },
                        reason: reason
                    })
                });
                const data = await res.json();

                if (data.success) {
                    closeAddServiceModal();
                    // Set the value in the inputs for current use
                    const serviceInput = document.getElementById('joServiceType');
                    const serviceHidden = document.getElementById('joServiceTypeValue');
                    const servicePriceInput = document.getElementById('joServicePrice');
                    if (serviceInput) serviceInput.value = name;
                    if (serviceHidden) serviceHidden.value = name;
                    if (servicePriceInput) servicePriceInput.value = price;
                    
                    const svcMsg = data.auto_approved ? ('<i class="fas fa-check-circle"></i> Service "' + name + '" processed and added successfully!') : ('Request submitted successfully! Request ID: #' + data.request_id + '. Status: Pending Manager Approval. You can use "' + name + '" now.');
                    showTxnAlert(svcMsg, 'success');
                } else {
                    setAddServiceError(data.error || 'Submission failed.');
                }
            } catch (err) {
                setAddServiceError('Network error: ' + err.message);
            } finally {
                if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-paper-plane"></i> Submit for Approval'; }
            }
        }
        

        // Close service modal on backdrop click
        document.addEventListener('click', function(e) {
            const modal = document.getElementById('addServiceModal');
            if (modal && e.target === modal) closeAddServiceModal();
        });

        function onJoServicePriceInput() {
            // Price manually entered — live update cart if already added
            const svcType  = (document.getElementById('joServiceTypeValue')?.value || document.getElementById('joServiceType')?.value || '').trim();
            const svcPrice = parseFloat(document.getElementById('joServicePrice')?.value || 0);
            if (svcType) {
                const names = svcType.split(', ').map(s => s.trim()).filter(Boolean);
                let updated = false;
                names.forEach(name => {
                    const existingSvc = cart.find(i => i.item_type === 'service' && (i.product_name === name || i.product_name === svcType));
                    if (existingSvc && (names.length === 1 || existingSvc.unit_price <= 0)) {
                        existingSvc.unit_price = Math.max(0, svcPrice);
                        updated = true;
                    }
                });
                if (updated) {
                    renderCart();
                }
            }
            updateCheckoutBtn();
            if (typeof calcLoyaltyPoints === 'function') calcLoyaltyPoints();
        }

        function onJoLaborChargeInput() {
            const laborCharge = parseFloat((document.getElementById('joLaborCharge')?.value || '0').replace(/[^0-9.]/g, '')) || 0;
            const laborLabel = 'Tip';
            const existingLabor = cart.find(i => i.item_type === 'service' && (i.product_name === laborLabel || i.product_name === 'Labor Charge' || i.category === 'Labor' || i.category === 'Tip'));
            if (laborCharge > 0) {
                if (existingLabor) {
                    existingLabor.product_name = laborLabel;
                    existingLabor.category = 'Tip';
                    existingLabor.unit_price = laborCharge;
                } else {
                    const hasServiceInCart = cart.some(i => i.item_type === 'service');
                    if (hasServiceInCart) {
                        cart.push({
                            item_type:    'service',
                            product_name: laborLabel,
                            category:     'Tip',
                            size_variant: '',
                            product_id:   null,
                            quantity:     1,
                            unit_price:   laborCharge,
                        });
                    }
                }
            } else if (existingLabor) {
                cart = cart.filter(i => i.category !== 'Labor' && i.category !== 'Tip' && i.product_name !== 'Labor Charge' && i.product_name !== 'Tip');
            }
            renderCart();
            updateCheckoutBtn();
            if (typeof calcLoyaltyPoints === 'function') calcLoyaltyPoints();
        }

