        // ── Reset ALL — clears Job Order + Merchandise forms + cart ──────────
        function resetAll() {
            if (!confirm('Reset all fields and clear the cart?')) return;

            // Completely reset Job Order form & Vehicle Inspection
            if (typeof resetJobOrderForm === 'function') {
                resetJobOrderForm();
            }
            if (typeof resetMerchandiseForm === 'function') {
                resetMerchandiseForm();
            }
            if (typeof window.resetVehicleInspection === 'function') {
                window.resetVehicleInspection();
            } else {
                document.querySelectorAll('input[name="jo_inspection[]"]').forEach(cb => {
                    cb.checked = false;
                    const lbl = cb.closest('label');
                    if (lbl) {
                        lbl.style.background = '#ffffff';
                        lbl.style.borderColor = '#e2e8f0';
                        lbl.style.fontWeight = '500';
                    }
                });
                const selAll = document.getElementById('joInspectSelectAll');
                if (selAll) { selAll.checked = false; selAll.indeterminate = false; }
                const inspRemarks = document.getElementById('joInspectionRemarks');
                if (inspRemarks) inspRemarks.value = '';
            }

            selectedCustomerIds.jo = null;
            selectedCustomerIds.merch = null;

            // ── Job Order fields ──────────────────────────────────────────────
            const joFields = ['joFirstName','joLastName','joContactNumber',
                              'joVehiclePlate','joServicePrice','joLaborCharge','joNotes',
                              'joEstimatedDuration','joYearModel','joEngineNumber',
                              'joChassisNumber','joOdometerReading','joCustomerComplaint',
                              'joRepairRecommendation'];
            joFields.forEach(id => {
                const el = document.getElementById(id);
                if (el) {
                    el.value = '';
                    el.readOnly = false;
                    el.style.background = '';
                }
            });
            // Reset service type input and hidden value
            const joServiceInput = document.getElementById('joServiceType');
            const joServiceHidden = document.getElementById('joServiceTypeValue');
            if (joServiceInput) joServiceInput.value = '';
            if (joServiceHidden) joServiceHidden.value = '';
            // Reset vehicle type and mechanic typeahead
            const vehicleInput = document.getElementById('joVehicleType');
            if (vehicleInput) vehicleInput.value = '';
            const mechInput = document.getElementById('joMechanic');
            if (mechInput) mechInput.value = '';
            const mechIdHid = document.getElementById('joMechanicId');
            if (mechIdHid) mechIdHid.value = '';
            const mechNameHid = document.getElementById('joMechanicName');
            if (mechNameHid) mechNameHid.value = '';
            hideMechanicDropdown();
            // Hide pricing notes and suggested parts
            const notesWrap = document.getElementById('joServicePriceNotes');
            const partsWrap = document.getElementById('joSuggestedParts');
            if (notesWrap) notesWrap.style.display = 'none';
            if (partsWrap) partsWrap.style.display = 'none';
            window._joSuggestedParts = [];

            const todayStrAll = new Date().toISOString().split('T')[0];
            const joDateEl = document.getElementById('joDate');
            if (joDateEl) joDateEl.value = todayStrAll;
            const joExpEl = document.getElementById('joExpectedRelease');
            if (joExpEl) joExpEl.value = todayStrAll;
            const priNorm = document.getElementById('joPriorityNormal');
            if (priNorm) priNorm.checked = true;

            // ── Merchandise fields ────────────────────────────────────────────
            const mFields = ['merchFirstName','merchLastName','merchContactNumber'];
            mFields.forEach(id => {
                const el = document.getElementById(id);
                if (el) el.value = '';
            });

            // ── Cart ──────────────────────────────────────────────────────────
            cart = [];
            renderCart();
            updateCheckoutBtn();

            // ── Payment panel ─────────────────────────────────────────────────
            const payMethod = document.getElementById('paymentMethod');
            if (payMethod) payMethod.selectedIndex = 0;
            clearPaymentInputs();
            onPaymentChange();
        }

        // ── Clear cart ────────────────────────────────────────────────────────
        function clearCart() {
            if (cart.length === 0) return;
            if (!confirm('Clear all items from the cart?')) return;
            cart = [];
            if (typeof updateServiceSelectionState === 'function') updateServiceSelectionState();
            hideServiceDropdown();
            renderCart();
            updateCheckoutBtn();
            syncProductCheckboxes();
        }

        // ── Render cart ───────────────────────────────────────────────────────
        function renderCart() {
            const body  = document.getElementById('cartBody');
            const empty = document.getElementById('cartEmpty');
            if (!body) return;

            if (cart.length === 0) {
                body.innerHTML = `<div class="cart-empty" id="cartEmpty">
                    <i class="fas fa-shopping-cart"></i>
                    Cart is empty.<br>Add service or items from the left.
                </div>`;
                updateTotals(0, 0, 0);
                return;
            }

            body.innerHTML = cart.map((item, idx) => {
                const subtotal = item.quantity * item.unit_price;
                const isTip = (item.product_name === 'Tip' || item.category === 'Tip' || item.product_name === 'Labor Charge');
                const icon = isTip ? 'fa-hand-holding-usd' : (item.item_type === 'service' ? 'fa-wrench' : 'fa-box');
                const color = isTip ? '#16a34a' : (item.item_type === 'service' ? '#b45309' : '#28a745');
                return `<div class="cart-item-row" style="display:flex;align-items:center;gap:8px;padding:8px 10px;border-bottom:1px solid #f1f5f9;">
                    <i class="fas ${icon}" style="color:${color};font-size:13px;flex-shrink:0;"></i>
                    <div style="flex:1;min-width:0;">
                        <div style="font-size:13.5px;font-weight:700;color:#0f172a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escHtml(item.product_name)}</div>
                        <div style="font-size:12px;font-weight:600;color:#475569;">₱${fmtNum(item.unit_price)} × ${item.quantity}</div>
                    </div>
                    <div style="display:flex;align-items:center;gap:4px;flex-shrink:0;">
                        <button type="button" onclick="cartQty(${idx},-1)" style="width:26px;height:26px;border:1.5px solid #cbd5e1;background:#f8fafc;border-radius:5px;cursor:pointer;font-size:15px;font-weight:800;line-height:1;display:flex;align-items:center;justify-content:center;padding:0;">−</button>
                        <span style="font-size:13.5px;font-weight:800;color:#0f172a;min-width:18px;text-align:center;">${item.quantity}</span>
                        <button type="button" onclick="cartQty(${idx},+1)" style="width:26px;height:26px;border:1.5px solid #cbd5e1;background:#f8fafc;border-radius:5px;cursor:pointer;font-size:15px;font-weight:800;line-height:1;display:flex;align-items:center;justify-content:center;padding:0;">+</button>
                    </div>
                    <div style="font-size:13.5px;font-weight:800;color:#002F70;text-align:right;flex-shrink:0;min-width:60px;">₱${fmtNum(subtotal)}</div>
                    <button type="button" onclick="cartRemove(${idx})" style="background:none;border:none;color:#dc2626;cursor:pointer;font-size:16px;font-weight:700;padding:0 4px;flex-shrink:0;" title="Remove">×</button>
                </div>`;
            }).join('');

            const gross = getGrossTotal();
            const discount = (typeof getLoyaltyDiscount === 'function') ? getLoyaltyDiscount(gross) : 0;
            const netGrand = Math.max(0, Math.round((gross - discount) * 100) / 100);

            const isVat = stationTaxConfig && stationTaxConfig.is_vat_registered;
            const taxRate = isVat ? (stationTaxConfig.tax_rate || 0.12) : 0;
            let vatableSales = 0;
            let vatAmount = 0;
            if (isVat && netGrand > 0) {
                vatableSales = Math.round((netGrand / (1 + taxRate)) * 100) / 100;
                vatAmount = Math.round((netGrand - vatableSales) * 100) / 100;
            } else {
                vatableSales = isVat ? 0 : netGrand;
                vatAmount = 0;
            }

            updateTotals(vatableSales, vatAmount, netGrand);
            if (typeof syncProductCheckboxes === 'function') syncProductCheckboxes();
            if (typeof syncServiceCheckboxes === 'function') syncServiceCheckboxes();

            window.cart = cart;
        }

        function cartQty(idx, delta) {
            const item = cart[idx];
            if (!item) return;
            const newQty = item.quantity + delta;
            if (newQty < 1) { cartRemove(idx); return; }
            if (item.item_type === 'merchandise') {
                const opt = document.querySelector(`#productSelect option[value="${item.product_id}"]`);
                const stock = opt ? parseInt(opt.dataset.stock || 0) : 9999;
                if (stock > 0 && newQty > stock) {
                    showTxnAlert(`Only ${stock} unit(s) available in stock.`, 'warning'); return;
                }
            }
            item.quantity = newQty;
            if (selectedProduct && String(selectedProduct.id) === String(item.product_id)) {
                const qtyEl = document.getElementById('itemQty');
                if (qtyEl) qtyEl.value = newQty;
            }
            renderCart();
            updateCheckoutBtn();
        }

        function cartRemove(idx) {
            const item = cart[idx];
            cart.splice(idx, 1);
            if (item && item.item_type === 'service' && item.category !== 'Labor' && item.category !== 'Tip' && item.product_name !== 'Labor Charge' && item.product_name !== 'Tip') {
                if (typeof updateServiceSelectionState === 'function') updateServiceSelectionState();
                hideServiceDropdown();
            } else {
                renderCart();
                updateCheckoutBtn();
                syncProductCheckboxes();
                if (typeof syncServiceCheckboxes === 'function') syncServiceCheckboxes();
            }
        }

        function updateTotals(vatable, vat, grand) {
            const s = document.getElementById('cartSubtotal');
            const v = document.getElementById('cartVat');
            const g = document.getElementById('cartGrandTotal');
            const sLabel = document.getElementById('cartSubtotalLabel');
            const vLabel = document.getElementById('cartVatLabel');
            const discRow = document.getElementById('cartLoyaltyDiscountRow');
            const discVal = document.getElementById('cartLoyaltyDiscount');
            const discInput = document.getElementById('loyaltyDiscountAmount');

            const gross = getGrossTotal();
            const discount = (typeof getLoyaltyDiscount === 'function') ? getLoyaltyDiscount(gross) : 0;
            const netGrand = (typeof grand === 'number' && grand >= 0) ? grand : Math.max(0, Math.round((gross - discount) * 100) / 100);

            const isVat = stationTaxConfig && stationTaxConfig.is_vat_registered;
            const taxRate = isVat ? (stationTaxConfig.tax_rate || 0.12) : 0;

            let vatableSales = vatable;
            let vatAmount = vat;
            if (typeof vatable !== 'number' || typeof vat !== 'number') {
                if (isVat && netGrand > 0) {
                    vatableSales = Math.round((netGrand / (1 + taxRate)) * 100) / 100;
                    vatAmount = Math.round((netGrand - vatableSales) * 100) / 100;
                } else {
                    vatableSales = isVat ? 0 : netGrand;
                    vatAmount = 0;
                }
            }

            if (sLabel) sLabel.textContent = isVat ? 'Vatable Sales' : 'Non-VAT Sales';
            if (vLabel) vLabel.textContent = isVat ? `VAT (${Math.round(taxRate * 100)}%)` : 'VAT (0%)';

            if (s) s.textContent = '₱' + fmtNum(vatableSales);
            if (v) v.textContent = '₱' + fmtNum(vatAmount);
            if (discRow && discVal) {
                if (discount > 0) {
                    discRow.style.display = 'flex';
                    discVal.textContent = '-₱' + fmtNum(discount);
                } else {
                    discRow.style.display = 'none';
                    discVal.textContent = '-₱0.00';
                }
            }
            if (discInput) discInput.value = '₱' + fmtNum(discount);
            if (g) g.textContent = '₱' + fmtNum(netGrand);

            const method = document.getElementById('paymentMethod')?.value || 'Cash';
            if (method === 'Cash') {
                const at = document.getElementById('amountTendered');
                if (at && (!at.value || parseFloat(at.value) === 0)) {
                    at.value = netGrand > 0 ? netGrand.toFixed(2) : '';
                }
            }
            computeChange();
            updateLoyaltyPointsEarned(netGrand);
        }

        function fmtNum(n) {
            return Number(n || 0).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        }

        function escHtml(s) {
            return String(s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
        }

        // ── Payment panel ─────────────────────────────────────────────────────
        window.onPaymentChange = function onPaymentChange() {
            const method = document.getElementById('paymentMethod')?.value || '';
            const isCard = (method === 'Card' || method === 'Credit Card' || method === 'Debit Card');
            const isEwallet = (method === 'E-Wallet' || method === 'GCash' || method === 'Maya');
            const isPvc = (method === 'Petron Value Card (PVC Points)');

            const containers = {
                'cashFields':           method === 'Cash',
                'cardFields':           isCard,
                'creditCardFields':     false,
                'debitCardFields':      false,
                'ewalletFields':        isEwallet,
                'pvcPointsFields':      isPvc,
                'fleetCardFields':      false,
                'efuelCardFields':      false,
                'creditAccountFields':  method === 'Credit Account'
            };
            for (const [id, show] of Object.entries(containers)) {
                const el = document.getElementById(id);
                if (el) el.style.display = show ? 'block' : 'none';
            }

            if (method === 'GCash' || method === 'Maya') {
                const prov = document.getElementById('ewProvider');
                if (prov) prov.value = method;
            }

            const generalBalanceWrap = document.getElementById('generalBalanceWrap');
            const needsBalance = ['Card','Credit Card','Debit Card','E-Wallet','GCash','Maya'].includes(method);
            if (generalBalanceWrap) generalBalanceWrap.style.display = needsBalance ? 'block' : 'none';

            if (isPvc) {
                // Ensure customer is linked and calculate redemption
                let activeCustomer = null;
                const custId = selectedCustomerIds.jo || selectedCustomerIds.merch;
                if (custId && Array.isArray(customerData)) {
                    activeCustomer = customerData.find(c => c.id == custId);
                }
                const pvcCardDisplay = document.getElementById('pvcCardNumberDisplay');
                const pvcAvailEl = document.getElementById('pvcAvailablePoints');
                const pvcNotice = document.getElementById('pvcCustomerNotice');

                if (activeCustomer && activeCustomer.has_pvc_card) {
                    if (pvcCardDisplay) pvcCardDisplay.value = activeCustomer.pvc_card_number;
                    if (pvcAvailEl) pvcAvailEl.value = activeCustomer.pvc_points_balance || activeCustomer.points || 0;
                    if (pvcNotice) pvcNotice.style.display = 'none';
                } else {
                    if (pvcCardDisplay) pvcCardDisplay.value = 'No linked card';
                    if (pvcAvailEl) pvcAvailEl.value = '0';
                    if (pvcNotice) pvcNotice.style.display = 'block';
                }
                calcLoyaltyPoints();
            } else {
                const grand = getGrandTotal();
                const prefillMap = {
                    'Cash': 'amountTendered',
                    'Card': 'cardAmount', 'Credit Card': 'cardAmount', 'Debit Card': 'cardAmount',
                    'E-Wallet': 'ewAmount', 'GCash': 'ewAmount', 'Maya': 'ewAmount'
                };
                const fillId = prefillMap[method];
                if (fillId) {
                    const inp = document.getElementById(fillId);
                    if (inp && (!inp.value || parseFloat(inp.value) === 0)) inp.value = grand > 0 ? grand.toFixed(2) : '';
                }
                calcLoyaltyPoints();
            }

            computeChange();
            onPaymentAmountInput();
            updatePaymentStatusBadge();
            updateCheckoutBtn();
        }

        window.onCreditCustomerChange = function onCreditCustomerChange() {
            const select = document.getElementById('creditCustomer');
            const compInput = document.getElementById('creditCompanyName');
            const accInput  = document.getElementById('creditAccountNumber');
            if (select && select.value) {
                const opt  = select.options[select.selectedIndex];
                const name = opt.getAttribute('data-name') || '';
                if (compInput) compInput.value = name;
                if (accInput && !accInput.value) accInput.value = 'ACC-' + String(select.value).padStart(5, '0');
            } else {
                if (compInput) compInput.value = '';
                if (accInput)  accInput.value  = '';
            }
            updatePaymentStatusBadge();
            updateCheckoutBtn();
        }

        function _getAmountPaid(method) {
            if (method === 'Petron Value Card (PVC Points)') {
                const gross = typeof getGrossTotal === 'function' ? getGrossTotal() : 0;
                return typeof getLoyaltyDiscount === 'function' ? getLoyaltyDiscount(gross) : 0;
            }
            const idMap = {
                'Cash': 'amountTendered',
                'Card': 'cardAmount',
                'Credit Card': 'cardAmount',
                'Debit Card': 'cardAmount',
                'E-Wallet': 'ewAmount',
                'GCash': 'ewAmount',
                'Maya': 'ewAmount'
            };
            const id = idMap[method];
            let val = id ? parseFloat(document.getElementById(id)?.value || 0) : 0;
            if (!val && (method === 'Card' || method === 'Credit Card' || method === 'Debit Card')) {
                val = parseFloat(document.getElementById('cardAmount')?.value || document.getElementById('ccAmount')?.value || document.getElementById('dcAmount')?.value || 0);
            }
            if ((!val || val <= 0) && method === 'Cash') {
                const grand = getGrandTotal();
                if (grand > 0) return grand;
            }
            return isNaN(val) ? 0 : val;
        }

        window.onPaymentAmountInput = function onPaymentAmountInput() {
            const method = document.getElementById('paymentMethod')?.value || '';
            if (method === 'Cash' || method === 'Credit Account' || !method) return;
            const amount = _getAmountPaid(method);
            const grand  = getGrandTotal();
            const balEl  = document.getElementById('generalBalanceDue');
            if (balEl) {
                const bal = Math.max(0, grand - amount);
                balEl.value = (grand > 0 && bal > 0) ? bal.toFixed(2) : '';
            }
            updatePaymentStatusBadge();
        }

        window.computeChange = function computeChange() {
            const grand       = getGrandTotal();
            const tenderedInp = document.getElementById('amountTendered');
            let tendered      = parseFloat(tenderedInp?.value || 0);
            const method      = document.getElementById('paymentMethod')?.value || 'Cash';
            if (method === 'Cash' && (!tendered || tendered <= 0) && grand > 0 && tenderedInp && !tenderedInp.value) {
                tendered = grand;
            }
            const changeWrap = document.getElementById('changeWrap');
            const changeEl   = document.getElementById('changeAmount');
            const balWrap    = document.getElementById('cashBalanceWrap');
            const balEl      = document.getElementById('cashBalanceDue');
            if (tendered >= grand && grand > 0) {
                if (changeWrap) changeWrap.style.display = 'block';
                if (changeEl)   changeEl.value = (tendered - grand).toFixed(2);
                if (balWrap)    balWrap.style.display = 'none';
                if (balEl)      balEl.value = '';
            } else {
                if (changeWrap) changeWrap.style.display = 'none';
                if (changeEl)   changeEl.value = '';
                const bal = Math.max(0, grand - tendered);
                if (balWrap) balWrap.style.display = grand > 0 ? 'block' : 'none';
                if (balEl)   balEl.value = bal > 0 ? bal.toFixed(2) : '';
            }
            updatePaymentStatusBadge();
        }

        // ── Live payment status badge ─────────────────────────────────────────
        function updatePaymentStatusBadge() {
            const method = document.getElementById('paymentMethod')?.value || '';
            const wrap   = document.getElementById('payStatusBadgeWrap');
            const icon   = document.getElementById('payStatusIcon');
            const lbl    = document.getElementById('payStatusLabel');
            const sub    = document.getElementById('payStatusSub');
            if (!wrap || !method) { if (wrap) wrap.style.display = 'none'; return; }

            const grand = getGrandTotal();
            let status, color, border, bg, iconClass, subText = '';

            if (method === 'Credit Account') {
                status = 'Pending'; color = '#6b21a8'; border = '#d8b4fe'; bg = '#f3e8ff';
                iconClass = 'fas fa-handshake';
                const sel = document.getElementById('creditCustomer');
                const acct = (sel && sel.selectedIndex > 0)
                    ? (sel.options[sel.selectedIndex].getAttribute('data-name') || 'Selected Account')
                    : 'Credit Account';
                subText = 'Charged to ' + acct + '. Full amount on credit.';
            } else {
                const amountPaid = _getAmountPaid(method);
                if (amountPaid <= 0 || grand === 0) {
                    status = 'Pending'; color = '#9a3412'; border = '#fed7aa'; bg = '#ffedd5';
                    iconClass = 'fas fa-clock';
                    subText = grand > 0 ? 'No amount encoded. Balance due: ₱' + fmtNum(grand) : 'Add items first.';
                } else if (amountPaid < grand - 0.009) {
                    status = 'Partially Paid'; color = '#92400e'; border = '#fde68a'; bg = '#fef9c3';
                    iconClass = 'fas fa-exclamation-circle';
                    subText = 'Paid ₱' + fmtNum(amountPaid) + ' — Balance: ₱' + fmtNum(grand - amountPaid);
                } else {
                    status = 'Paid'; color = '#166534'; border = '#86efac'; bg = '#dcfce7';
                    iconClass = 'fas fa-check-circle';
                    let viaDesc = method;
                    if (method === 'E-Wallet') {
                        const prov = document.getElementById('ewProvider')?.value || 'GCash';
                        viaDesc = 'E-Wallet (' + prov + ')';
                    } else if (method === 'Card') {
                        const cat = document.getElementById('cardSubType')?.value || 'Card';
                        viaDesc = cat;
                    }
                    subText = method === 'Cash'
                        ? (amountPaid - grand > 0.009 ? 'Change: ₱' + fmtNum(amountPaid - grand) : 'Exact amount paid.')
                        : 'Full amount received via ' + viaDesc + '.';
                }
            }

            wrap.style.display = 'flex';
            wrap.style.background = bg;
            wrap.style.borderColor = border;
            if (icon) { icon.className = iconClass; icon.style.color = color; }
            if (lbl)  { lbl.textContent = status; lbl.style.color = color; }
            if (sub)  { sub.textContent = subText; }
        }

        function updateCheckoutBtn() {
            const btn    = document.getElementById('checkoutBtn');
            const method = document.getElementById('paymentMethod')?.value || '';
            if (!btn) return;
            const hasPendingSvc = ((document.getElementById('joServiceTypeValue')?.value || document.getElementById('joServiceType')?.value || '').trim() !== '') && ((parseFloat(document.getElementById('joServicePrice')?.value || 0) > 0) || (parseFloat((document.getElementById('joLaborCharge')?.value || '0').replace(/[^0-9.]/g, '')) > 0));
            let disabled = (cart.length === 0 && !hasPendingSvc) || !method;
            if (method === 'Credit Account') {
                if (!document.getElementById('creditCustomer')?.value) disabled = true;
            }
            btn.disabled = disabled;
        }

        // ── Submit transaction ────────────────────────────────────────────────
        function _resetSubmitBtn() {
            _isSubmittingTxn = false;
            const b = document.getElementById('checkoutBtn');
            if (b) { b.disabled = false; b.innerHTML = '<i class="fas fa-receipt"></i> Process & Print Receipt'; }
            updateCheckoutBtn();
        }

        var _isSubmittingTxn = false;
        async function submitMerchTxn() {
            if (_isSubmittingTxn) return;
            _isSubmittingTxn = true;
            const btn = document.getElementById('checkoutBtn');
            if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing…'; }

            try {
                // Auto-commit Job Order service to cart if configured in form but not yet committed
                const pendingSvcType = (document.getElementById('joServiceTypeValue')?.value || document.getElementById('joServiceType')?.value || '').trim();
                const pendingSvcPrice = parseFloat(document.getElementById('joServicePrice')?.value || 0);
                const pendingLabor = parseFloat((document.getElementById('joLaborCharge')?.value || '0').replace(/[^0-9.]/g, '')) || 0;
                if (pendingSvcType && (pendingSvcPrice > 0 || pendingLabor > 0) && !cart.some(i => i.item_type === 'service')) {
                    await applyJobOrderToCart();
                }

                if (cart.length === 0) {
                    showTxnAlert('Cart is empty.', 'warning');
                    _resetSubmitBtn();
                    return;
                }

                const method = document.getElementById('paymentMethod')?.value || '';
                if (!method) {
                    showTxnAlert('Please select a payment method.', 'warning');
                    _resetSubmitBtn();
                    return;
                }

                const gross = getGrossTotal();
                const loyaltyDiscount = getLoyaltyDiscount(gross);
                const grand = getGrandTotal();
                const hasService = cart.some(i => i.item_type === 'service');
                const activeCustomerPrefix = hasService ? 'jo' : 'merch';
                let firstName = '', lastName = '', contactNumber = '';
                firstName     = (document.getElementById('joFirstName')?.value || document.getElementById('merchFirstName')?.value || '').trim();
                lastName      = (document.getElementById('joLastName')?.value  || document.getElementById('merchLastName')?.value  || '').trim();
                contactNumber = (document.getElementById('joContactNumber')?.value || document.getElementById('merchContactNumber')?.value || '').trim();
                if (!firstName) { showTxnAlert('Please enter the customer\'s first name.', 'warning'); _resetSubmitBtn(); return; }
                let selectedCustomerId = selectedCustomerIds.jo || selectedCustomerIds.merch || null;
                const fullName = [firstName, lastName].filter(Boolean).join(' ') || firstName || 'Walk-in Customer';

            if (method === 'Credit Account') {
                if (!document.getElementById('creditCustomer')?.value) {
                    showTxnAlert('Please select a credit account.', 'warning'); _resetSubmitBtn(); return;
                }
            }

            const isPvc = (method === 'Petron Value Card (PVC Points)');
            if (isPvc) {
                if (!selectedCustomerId) {
                    showTxnAlert('A registered customer is required to redeem Petron Value Card (PVC Points).', 'warning');
                    _resetSubmitBtn(); return;
                }
                const activeCust = Array.isArray(customerData) ? customerData.find(c => c.id == selectedCustomerId) : null;
                if (!activeCust || !activeCust.has_pvc_card) {
                    showTxnAlert('The selected customer does not have an active linked Petron Value Card (PVC).', 'warning');
                    _resetSubmitBtn(); return;
                }
                const availPts = parseInt(activeCust.pvc_points_balance || activeCust.points || 0, 10) || 0;
                if (availPts <= 0) {
                    showTxnAlert('Selected customer has 0 PVC points available to redeem.', 'warning');
                    _resetSubmitBtn(); return;
                }
            }

            const loyaltyProgram = document.getElementById('loyaltyProgram')?.value || 'No Loyalty';
            const loyaltyCardNo = (document.getElementById('loyaltyCardNo')?.value || document.getElementById('pvcCardNumberDisplay')?.value || '').trim();
            const loyaltyPointsBalance = parseInt(document.getElementById('loyaltyPointsBalance')?.value || document.getElementById('pvcAvailablePoints')?.value || 0) || 0;
            const loyaltyPointsEarned = parseInt(document.getElementById('loyaltyPointsEarned')?.value || 0) || 0;
            const loyaltyPointsRedeemed = isPvc ? (parseInt(document.getElementById('pvcPointsRedeemed')?.value || 0, 10) || 0) : (parseInt(document.getElementById('loyaltyPointsRedeemed')?.value || 0) || 0);
            const hasLoyaltyCard = isPvc || (loyaltyProgram !== 'No Loyalty' && (loyaltyCardNo !== '' || selectedCustomerId !== null));

            if (!isPvc && loyaltyProgram !== 'No Loyalty' && loyaltyPointsRedeemed > loyaltyPointsBalance) {
                showTxnAlert(`Cannot redeem more points than current balance (${loyaltyPointsBalance} pts).`, 'warning');
                document.getElementById('loyaltyPointsRedeemed')?.focus();
                _resetSubmitBtn(); return;
            }

            let joData = {};
            if (hasService) {
                const mechanicId = (document.getElementById('joMechanicId')?.value || '').trim();
                if (!mechanicId) {
                    showTxnAlert('Please select a valid assigned mechanic from the dropdown list.', 'warning');
                    const mechInput = document.getElementById('joMechanic');
                    if (mechInput) mechInput.focus();
                    _resetSubmitBtn(); return;
                }
                joData = {
                    job_order_service:            (document.getElementById('joServiceTypeValue')?.value || '').trim(),
                    job_order_description:        (document.getElementById('joNotes')?.value || '').trim(),
                    job_order_vehicle_plate:      (document.getElementById('joVehiclePlate')?.value || '').trim().toUpperCase(),
                    job_order_vehicle_type:       (document.getElementById('joVehicleType')?.value || '').trim(),
                    job_order_vehicle_brand:      (document.getElementById('joVehicleBrand')?.value || '').trim(),
                    job_order_vehicle_model:      (document.getElementById('joVehicleModel')?.value || '').trim(),
                    job_order_year_model:         (document.getElementById('joYearModel')?.value || '').trim(),
                    job_order_engine_number:      (document.getElementById('joEngineNumber')?.value || '').trim(),
                    job_order_chassis_number:     (document.getElementById('joChassisNumber')?.value || '').trim(),
                    job_order_mechanic_id:        parseInt(mechanicId) || null,
                    job_order_mechanic_name:      (document.getElementById('joMechanicName')?.value || '').trim(),
                    job_order_contact:            contactNumber,
                    job_order_estimated_duration: (document.getElementById('joEstimatedDuration')?.value?.trim() !== '' && parseInt(document.getElementById('joEstimatedDuration').value) > 0) ? parseInt(document.getElementById('joEstimatedDuration').value) : null,
                };
            }

            let amountPaid = _getAmountPaid(method);
            if (method === 'Cash' && (!amountPaid || amountPaid <= 0)) {
                amountPaid = grand;
            }
            let paymentStatus;
            if (method === 'Credit Account') {
                paymentStatus = 'Pending';
            } else if (isPvc) {
                if (grand <= 0.009) {
                    paymentStatus = 'Paid';
                } else if (amountPaid >= grand - 0.009) {
                    paymentStatus = 'Paid';
                } else {
                    paymentStatus = 'Partially Paid';
                }
            } else if (amountPaid <= 0) {
                paymentStatus = 'Pending';
            } else if (amountPaid < grand - 0.009) {
                paymentStatus = 'Partially Paid';
            } else {
                paymentStatus = 'Paid';
            }
            const balanceDue = method === 'Credit Account' ? grand
                : (paymentStatus === 'Paid' ? 0 : Math.max(0, grand - amountPaid));

            const isCard          = method === 'Card' || method === 'Credit Card' || method === 'Debit Card';
            const isEwallet       = method === 'E-Wallet' || method === 'GCash' || method === 'Maya';
            const isCredit        = method === 'Credit Account';

            // Canonical top-level payment method
            const canonicalPaymentMethod = isCard ? 'Card'
                                         : isEwallet ? 'E-Wallet'
                                         : isPvc ? 'Petron Value Card (PVC Points)'
                                         : method;

            const ewProviderVal = isEwallet ? (
                document.getElementById('ewProvider')?.value || (method === 'Maya' ? 'Maya' : 'GCash')
            ) : null;

            const cardSubTypeVal = isCard ? (
                document.getElementById('cardSubType')?.value || (method === 'Debit Card' ? 'Debit Card' : 'Credit Card')
            ) : null;
            const cardNetworkVal = isCard ? (
                document.getElementById('cardType')?.value || document.getElementById('ccType')?.value || document.getElementById('dcType')?.value || null
            ) : null;
            const cardLastFourVal = isCard ? (
                document.getElementById('cardLastFour')?.value || document.getElementById('ccLastFour')?.value || null
            ) : null;
            const cardRefVal = isCard ? (
                document.getElementById('cardRefNumber')?.value || document.getElementById('ccRefNumber')?.value || document.getElementById('dcRefNumber')?.value || null
            ) : null;

            const isVat = stationTaxConfig && stationTaxConfig.is_vat_registered;
            const taxRate = isVat ? (stationTaxConfig.tax_rate || 0.12) : 0;
            const vatableSales = isVat ? (grand > 0 ? Math.round((grand / (1 + taxRate)) * 100) / 100 : 0) : grand;
            const vatAmount = isVat ? (grand > 0 ? Math.round((grand - vatableSales) * 100) / 100 : 0) : 0;

            const payload = {
                action:                  'create_transaction',
                subtotal:                parseFloat(vatableSales.toFixed(2)),
                vat_amount:              parseFloat(vatAmount.toFixed(2)),
                discount_amount:         parseFloat(loyaltyDiscount.toFixed(2)),
                loyalty_discount_amount: parseFloat(loyaltyDiscount.toFixed(2)),
                total_amount:            parseFloat(grand.toFixed(2)),
                customer_id:             selectedCustomerId,
                customer_first_name:     firstName || null,
                customer_last_name:      lastName  || null,
                customer_contact:        contactNumber || null,
                customer_name:           fullName,
                payment_method:          canonicalPaymentMethod,
                amount_paid:             isPvc ? (amountPaid > 0 ? amountPaid : (grand <= 0.009 ? 0 : null)) : (amountPaid > 0 ? amountPaid : (method === 'Cash' ? grand : null)),
                amount_tendered:         method === 'Cash' ? (amountPaid > 0 ? amountPaid : grand) : null,
                change_amount:           method === 'Cash' && amountPaid >= grand ? parseFloat((amountPaid - grand).toFixed(2)) : null,
                balance_due:             balanceDue > 0 ? parseFloat(balanceDue.toFixed(2)) : null,
                payment_status:          paymentStatus,

                card_type:           cardNetworkVal || cardSubTypeVal,
                card_sub_type:       cardSubTypeVal,
                card_last_four:      cardLastFourVal,
                card_reference:      cardRefVal,

                ewallet_provider:    ewProviderVal,
                ewallet_reference:   isEwallet ? (document.getElementById('ewRefNumber')?.value || null) : null,

                credit_customer_id:    isCredit ? (parseInt(document.getElementById('creditCustomer')?.value) || null) : null,
                credit_company_name:   isCredit ? (document.getElementById('creditCompanyName')?.value || null) : null,
                credit_account_number: isCredit ? (document.getElementById('creditAccountNumber')?.value || null) : null,
                credit_po_number:      isCredit ? (document.getElementById('creditPoNumber')?.value || null) : null,
                credit_due_date:       isCredit ? (document.getElementById('creditDueDate')?.value || null) : null,
                
                loyalty_type:            (isPvc || loyaltyProgram !== 'No Loyalty') ? 'Petron Value Card (PVC)' : null,
                loyalty_card_no:         (isPvc || hasLoyaltyCard) ? (loyaltyCardNo || null) : null,
                loyalty_points_earned:   (hasLoyaltyCard) ? loyaltyPointsEarned : null,
                loyalty_points_redeemed: (hasLoyaltyCard) ? loyaltyPointsRedeemed : null,

                items: cart.map(i => ({
                    item_type:    i.item_type,
                    product_id:   i.product_id,
                    product_name: i.product_name,
                    category:     i.category,
                    size_variant: i.size_variant,
                    quantity:     i.quantity,
                    unit_price:   i.unit_price,
                })),
                ...joData,
            };

            const res  = await fetch('../backend/api/merchandise_transactions.php', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    credentials: 'same-origin',
                    body: JSON.stringify(payload),
                });
                const data = await res.json();

                if (data.success) {
                    const txnId = data.transaction_id || data.merch_transaction_id;

                    // Update in-memory customer points balance so UI stays fresh
                    if (selectedCustomerId && loyaltyProgram !== 'No Loyalty' && Array.isArray(customerData)) {
                        const matchedCust = customerData.find(c => c.id == selectedCustomerId);
                        if (matchedCust) {
                            matchedCust.points = Math.max(0, loyaltyPointsBalance + loyaltyPointsEarned - loyaltyPointsRedeemed);
                        }
                    }

                    // Automatically open / print the official receipt (for BOTH Job Orders & Merchandise transactions)
                    if (txnId) {
                        printMerchandiseReceipt(txnId);
                    }

                    // Reset cart and checkout state
                    cart = [];
                    renderCart();
                    updateCheckoutBtn();

                    // Completely reset Job Order form & Vehicle Inspection
                    if (typeof resetJobOrderForm === 'function') {
                        resetJobOrderForm();
                    }
                    if (typeof resetMerchandiseForm === 'function') {
                        resetMerchandiseForm();
                    }
                    if (typeof window.resetVehicleInspection === 'function') {
                        window.resetVehicleInspection();
                    } else {
                        document.querySelectorAll('input[name="jo_inspection[]"]').forEach(cb => {
                            cb.checked = false;
                            const lbl = cb.closest('label');
                            if (lbl) {
                                lbl.style.background = '#ffffff';
                                lbl.style.borderColor = '#e2e8f0';
                                lbl.style.fontWeight = '500';
                            }
                        });
                        const selAll = document.getElementById('joInspectSelectAll');
                        if (selAll) { selAll.checked = false; selAll.indeterminate = false; }
                        const inspRemarks = document.getElementById('joInspectionRemarks');
                        if (inspRemarks) inspRemarks.value = '';
                    }

                    selectedCustomerIds.jo = null;
                    selectedCustomerIds.merch = null;

                    // Extra reset safeguard for JO inputs
                    ['joFirstName','joLastName','joContactNumber','joVehiclePlate',
                     'joServicePrice','joLaborCharge','joNotes','joEstimatedDuration',
                     'joYearModel','joEngineNumber','joChassisNumber','joOdometerReading',
                     'joCustomerComplaint','joRepairRecommendation'].forEach(id => {
                        const el = document.getElementById(id);
                        if (el) {
                            el.value = '';
                            el.readOnly = false;
                            el.style.background = '';
                        }
                    });
                    const joSvcInput = document.getElementById('joServiceType');
                    const joSvcHidden = document.getElementById('joServiceTypeValue');
                    if (joSvcInput) joSvcInput.value = '';
                    if (joSvcHidden) joSvcHidden.value = '';
                    const joVehicleSel = document.getElementById('joVehicleType');
                    if (joVehicleSel) joVehicleSel.value = '';
                    
                    const joMech = document.getElementById('joMechanic');
                    if (joMech) joMech.value = '';
                    const joMechId = document.getElementById('joMechanicId');
                    if (joMechId) joMechId.value = '';
                    const joMechNm = document.getElementById('joMechanicName');
                    if (joMechNm) joMechNm.value = '';
                    if (typeof hideMechanicDropdown === 'function') hideMechanicDropdown();
                    const notesWrap = document.getElementById('joServicePriceNotes');
                    if (notesWrap) notesWrap.style.display = 'none';
                    const mechBusyWarn = document.getElementById('joMechanicBusyWarn');
                    if (mechBusyWarn) mechBusyWarn.style.display = 'none';
                    if (typeof clearSuggestedParts === 'function') clearSuggestedParts();

                    const todayStrTxn = new Date().toISOString().split('T')[0];
                    const joDateTxn = document.getElementById('joDate');
                    if (joDateTxn) joDateTxn.value = todayStrTxn;
                    const joExpTxn = document.getElementById('joExpectedRelease');
                    if (joExpTxn) joExpTxn.value = todayStrTxn;
                    const priNormTxn = document.getElementById('joPriorityNormal');
                    if (priNormTxn) priNormTxn.checked = true;

                    // Reset merch customer fields
                    ['merchFirstName','merchLastName','merchContactNumber'].forEach(id => {
                        const el = document.getElementById(id);
                        if (el) el.value = '';
                    });
                    const pmSel = document.getElementById('paymentMethod');
                    if (pmSel) pmSel.selectedIndex = 0;
                    if (typeof onPaymentChange === 'function') onPaymentChange();

                    // If job order (has service), show clean banner alert without redundant buttons
                    if (hasService) {
                        showTxnAlert('Job Order processed successfully! Official Receipt opened for printing.', 'success');
                        return;
                    }

                    showTxnAlert('Transaction submitted successfully! Receipt opened in a new tab.', 'success');
                } else {
                    showTxnAlert('Error: ' + (data.error || 'Transaction failed.'), 'error');
                }
            } catch (err) {
                showTxnAlert('Network error: ' + err.message, 'error');
            } finally {
                _isSubmittingTxn = false;
                if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-receipt"></i> Process & Print Receipt'; }
                updateCheckoutBtn();
            }
        }

        // ── Alert helper ──────────────────────────────────────────────────────
        // ── Alert helper (Right-side Floating Banner) ──────────────────────────
        function showTxnAlert(msg, type) {
            const colors = {
                success: { bg: '#f0fdf4', border: '#86efac', color: '#166534' },
                warning: { bg: '#fffbeb', border: '#fde68a', color: '#92400e' },
                error:   { bg: '#fef2f2', border: '#fecaca', color: '#991b1b' },
                info:    { bg: '#eff6ff', border: '#bfdbfe', color: '#1e40af' },
            };
            const c = colors[type] || colors.info;
            const icons = { success: 'fa-check-circle', warning: 'fa-exclamation-triangle', error: 'fa-times-circle', info: 'fa-info-circle' };
            const icon = icons[type] || icons.info;

            // Remove existing alert
            const old = document.getElementById('txnAlertBanner');
            if (old) old.remove();

            const div = document.createElement('div');
            div.id = 'txnAlertBanner';
            div.style.cssText = `position:fixed;top:84px;right:22px;left:auto;transform:none;z-index:999999;
                background:${c.bg};border:1.5px solid ${c.border};color:${c.color};
                padding:12px 18px;border-radius:10px;font-size:13.5px;font-weight:700;
                display:flex;align-items:center;gap:10px;box-shadow:0 12px 30px rgba(0,0,0,.15);
                max-width:440px;width:auto;`;
            div.innerHTML = `<i class="fas ${icon}" style="font-size:16px;flex-shrink:0;"></i><span style="flex:1;">${escHtml(msg)}</span>`;
            document.body.appendChild(div);
            setTimeout(() => { if (div.parentElement) div.remove(); }, 3000);
        }

        // ── Init ──────────────────────────────────────────────────────────────
        document.addEventListener('DOMContentLoaded', function() {
            cart = [];
            window.cart = [];

            // Reset vehicle inspection to default unchecked state
            if (typeof window.resetVehicleInspection === 'function') {
                window.resetVehicleInspection();
            }

            // Set default date and priority for Job Order
            const todayStrInit = new Date().toISOString().split('T')[0];
            const joDateInit = document.getElementById('joDate');
            if (joDateInit && !joDateInit.value) {
                joDateInit.value = todayStrInit;
            }
            const joExpInit = document.getElementById('joExpectedRelease');
            if (joExpInit && !joExpInit.value) {
                joExpInit.value = todayStrInit;
            }
            const priNormInit = document.getElementById('joPriorityNormal');
            if (priNormInit && !document.querySelector('input[name="joPriority"]:checked')) {
                priNormInit.checked = true;
            }

            loadServiceTypes();
            loadVehicleTypes();
            renderCart();
            updateTotals(0, 0, 0);
            updateCheckoutBtn();
            onPaymentChange();

            // Close vehicle dropdown when clicking outside
            document.addEventListener('click', function(e) {
                const input = document.getElementById('joVehicleType');
                const dd    = document.getElementById('vehicleTypeDropdown');
                if (dd && input && !input.contains(e.target) && !dd.contains(e.target)) {
                    dd.style.display = 'none';
                }
            });
        });

        window.addEventListener('load', function() {
            const todayStrLoad = new Date().toISOString().split('T')[0];
            const joDateLoad = document.getElementById('joDate');
            if (joDateLoad && !joDateLoad.value) {
                joDateLoad.value = todayStrLoad;
            }
            const joExpLoad = document.getElementById('joExpectedRelease');
            if (joExpLoad && !joExpLoad.value) {
                joExpLoad.value = todayStrLoad;
            }
            if (!cart || cart.length === 0) {
                cart = [];
                window.cart = [];
                renderCart();
                updateTotals(0, 0, 0);
                updateCheckoutBtn();
            }
        });

        window.addEventListener('pageshow', function() {
            if (typeof window.resetVehicleInspection === 'function') {
                window.resetVehicleInspection();
            }
        });
        </script>

