                            <div style="font-weight:800;font-size:13.5px;color:<?= $wf_status==='Rejected' ? '#dc2626' : '#002F70' ?>;line-height:1.2;white-space:nowrap;">
                                <?= htmlspecialchars($jo_num_disp) ?>
