        <script>
        // ── Payment Settlement Modal JS ───────────────────────────────────────
        var _pmBalance = 0;
        var _pmMethod  = 'Cash';
        window._parentModalBeforePayment = null;

        function openPaymentModal(joId, joSource, total, alreadyPaid, balanceDue, customerName, markComplete, redirectTab) {
            _pmBalance = parseFloat(balanceDue) || 0;
            var fmt = function(n){ return parseFloat(n).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2}); };

            // Check if viewMerchandiseModal (or any parent modal) is currently visible
            var viewMerch = document.getElementById('viewMerchandiseModal');
            if (viewMerch && viewMerch.style.display !== 'none' && viewMerch.style.display !== '') {
                window._parentModalBeforePayment = 'viewMerchandiseModal';
                viewMerch.style.display = 'none';
            } else {
                window._parentModalBeforePayment = null;
            }

            document.getElementById('pmJoId').value         = joId;
            document.getElementById('pmJoSource').value     = joSource;
            document.getElementById('pmRedirectTab').value  = redirectTab || 'tracker';
            document.getElementById('pmMarkComplete').value = markComplete ? '1' : '';
            document.getElementById('pmTotal').textContent       = fmt(total);
            document.getElementById('pmAlreadyPaid').textContent = fmt(alreadyPaid);
            document.getElementById('pmBalanceDue').textContent  = fmt(balanceDue);

            // Colour balance cell
            var cell = document.getElementById('pmBalanceCell');
            var lbl  = document.getElementById('pmBalanceLbl');
            var val  = document.getElementById('pmBalanceDueWrap');
            if (_pmBalance > 0.009) {
                cell.style.background = '#fff3cd'; lbl.style.color = '#92400e'; val.style.color = '#9a3412';
            } else {
                cell.style.background = '#dcfce7'; lbl.style.color = '#166534'; val.style.color = '#166534';
            }

            // Already-paid + markComplete → skip payment form, show confirm-complete panel
            var alreadyPaidMode = markComplete && _pmBalance <= 0.009;

            var payForm        = document.getElementById('paymentSettleForm');
            var alreadyPaidSec = document.getElementById('pmAlreadyPaidSection');
            if (payForm)        payForm.style.display        = alreadyPaidMode ? 'none' : 'block';
            if (alreadyPaidSec) alreadyPaidSec.style.display = alreadyPaidMode ? 'block' : 'none';

            if (alreadyPaidMode) {
                // Populate the already-paid confirm form
                document.getElementById('pmAlreadyPaidJoId').value     = joId;
                document.getElementById('pmAlreadyPaidJoSource').value = joSource;
            } else {
                // Normal payment form — pre-fill amount only, NOT tendered (manual input)
                document.getElementById('pmAmountInput').value = _pmBalance > 0.009 ? _pmBalance.toFixed(2) : '';
                document.getElementById('pmTendered').value    = ''; // staff types this manually
                document.getElementById('pmRefInput').value    = '';
                document.getElementById('pmRemarks').value     = '';
                document.getElementById('pmChangeRow').style.display = 'none';
                document.getElementById('pmPreview').style.display   = 'none';

                // Reset dropdown to Cash
                var sel = document.getElementById('pmMethodSelect');
                if (sel) sel.value = 'Cash';
                pmSelectMethod('Cash');
            }

            // Complete notice
            var notice = document.getElementById('pmCompleteNotice');
            notice.style.display = (markComplete && !alreadyPaidMode) ? 'flex' : 'none';

            // Title / icon / submit label
            var title, submitLabel;
            if (alreadyPaidMode) {
                title = 'Mark Job Order Complete';
                submitLabel = 'Mark as Completed';
            } else if (markComplete) {
                title = 'Complete & Settle Payment';
                submitLabel = 'Complete & Confirm';
            } else {
                title = _pmBalance > 0.009 ? 'Settle Balance' : 'Record Payment';
                submitLabel = 'Record Payment';
            }
            document.getElementById('pmModalTitle').textContent    = title;
            document.getElementById('pmModalCustomer').textContent = customerName ? 'Customer: ' + customerName : '';
            document.getElementById('pmHeaderIcon').className      = markComplete ? 'fas fa-check-circle' : 'fas fa-receipt';
            if (document.getElementById('pmSubmitLabel'))
                document.getElementById('pmSubmitLabel').textContent = submitLabel;

            var payModal = document.getElementById('paymentSettleModal');
            if (payModal) {
                payModal.style.display = 'flex';
                payModal.style.zIndex = '10000000';
            }

            if (!alreadyPaidMode) {
                setTimeout(function(){
                    var focus = document.getElementById('pmAmountInput');
                    if (focus) focus.select();
                }, 80);
            }
        }

        function closePaymentModal() {
            var payModal = document.getElementById('paymentSettleModal');
            if (payModal) payModal.style.display = 'none';

            if (window._parentModalBeforePayment) {
                var parentId = window._parentModalBeforePayment;
                window._parentModalBeforePayment = null;
                var parentModal = document.getElementById(parentId);
                if (parentModal) {
                    parentModal.style.display = 'flex';
                    parentModal.style.zIndex = '9999999';
                }
            }
        }

        function pmSelectMethod(method) {
            _pmMethod = method;
            document.getElementById('pmMethodHidden').value = method;
            // Sync dropdown if it exists
            var sel = document.getElementById('pmMethodSelect');
            if (sel && sel.value !== method) sel.value = method;
            // Show/hide contextual fields
            document.getElementById('pmCashFields').style.display   = (method === 'Cash') ? 'block' : 'none';
            document.getElementById('pmRefFields').style.display    = ['Credit Card','Debit Card','GCash','Maya','Petron Value Card (PVC Points)'].includes(method) ? 'block' : 'none';
            document.getElementById('pmCreditFields').style.display = (method === 'Credit Account') ? 'block' : 'none';
            var labels = {
                'Credit Card':                   'Card Reference No.',
                'Debit Card':                    'Card Reference No.',
                'GCash':                         'GCash Reference No.',
                'Maya':                          'Maya Reference No.',
                'Petron Value Card (PVC Points)':'PVC Card / Auth No.'
            };
            var lbl = document.getElementById('pmRefLabel');
            if (lbl) lbl.textContent = labels[method] || 'Reference No.';
            pmRecalc();
        }

        function pmSetFull() {
            document.getElementById('pmAmountInput').value = _pmBalance.toFixed(2);
            if (_pmMethod === 'Cash') {
                document.getElementById('pmTendered').value = _pmBalance.toFixed(2);
                pmCalcChange();
            }
            pmRecalc();
        }

        function pmCalcChange() {
            var tendered = parseFloat(document.getElementById('pmTendered').value) || 0;
            var amount   = parseFloat(document.getElementById('pmAmountInput').value) || _pmBalance;
            var change   = tendered - amount;
            var row      = document.getElementById('pmChangeRow');
            if (tendered > 0 && change >= 0) {
                document.getElementById('pmChangeAmt').textContent =
                    change.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
                row.style.display = 'block';
            } else {
                row.style.display = 'none';
            }
        }

        function pmRecalc() {
            var amount  = parseFloat(document.getElementById('pmAmountInput').value) || 0;
            var preview = document.getElementById('pmPreview');
            if (amount <= 0) { preview.style.display = 'none'; return; }
            var newBal  = Math.max(0, _pmBalance - amount);
            var isPaid  = newBal <= 0.009;
            var status  = isPaid ? 'Paid' : 'Partially Paid';
            var fmt = function(n){ return '₱'+parseFloat(n).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2}); };
            document.getElementById('pmPreviewBalance').textContent = fmt(newBal);
            document.getElementById('pmPreviewBalance').style.color = isPaid ? '#166534' : '#9a3412';
            var badge = document.getElementById('pmPreviewStatusBadge');
            badge.textContent      = status;
            badge.style.background = isPaid ? '#dcfce7' : '#fef9c3';
            badge.style.color      = isPaid ? '#166534' : '#92400e';
            badge.style.border     = isPaid ? '1px solid #86efac' : '1px solid #fde68a';
            preview.style.display  = 'block';
            if (_pmMethod === 'Cash') pmCalcChange();
        }

        document.getElementById('paymentSettleModal').addEventListener('click', function(e){
            if (e.target === this) closePaymentModal();
        });

        document.getElementById('paymentSettleForm').addEventListener('submit', function(e){
            var amount = parseFloat(document.getElementById('pmAmountInput').value) || 0;
            if (amount <= 0) {
                e.preventDefault();
                var wrap = document.getElementById('pmAmountWrap');
                wrap.style.borderColor = '#dc2626';
                document.getElementById('pmAmountInput').focus();
                setTimeout(function(){ wrap.style.borderColor = '#d1d5db'; }, 15000);
            }
        });
        </script>
        </div><!-- /innerTab_tracker -->

        <!-- ══════════════════════════════════════════════════════════
             GLOBAL MODALS (Available across Merchandise & Tracker tabs)
        ══════════════════════════════════════════════════════════ -->
        
        <script>
        // ── Job Order Modal Functions ───────────────────────────────────────
        
        // View Job Order Details Modal
        // Store current JO ref for print
        var _currentViewJORef = '';
        var _currentViewJOSource = '';

        function viewJobOrderDetails(joData) {
            ['viewMerchandiseModal', 'updateStatusModal', 'adjustJobOrderModal', 'txnRequestModal', 'requestAdjustModal', 'requestVoidModal'].forEach(function(id) {
                var m = document.getElementById(id);
                if (m) m.style.display = 'none';
            });
            var fmt = function(n){ return '₱' + parseFloat(n || 0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2}); };
            var val = function(v, fallback) { return (v && v !== '' && v !== '0' && v !== 0) ? v : (fallback || '—'); };
            var setText = function(id, text) {
                var el = document.getElementById(id);
                if (el) el.textContent = text;
            };

            _currentViewJORef    = joData.jo_ref || '';
            _currentViewJOSource = joData.source || 'job_orders';

            setText('viewJORef', val(joData.jo_ref));
            setText('viewJORef2', val(joData.jo_ref));
            setText('viewJOTxnId', val(joData.jo_ref));
            setText('viewJOCustomer', val(joData.customer));

            // Build vehicle display: plate + type + brand/model/year
            var vParts = [];
            if (joData.vehicle_plate) vParts.push(joData.vehicle_plate);
            if (joData.vehicle_type) vParts.push('(' + joData.vehicle_type + ')');
            setText('viewJOVehicle', vParts.length ? vParts.join(' ') : '—');

            var brandModelParts = [];
            var vb = val(joData.vehicle_brand, '');
            var vm = val(joData.vehicle_model, '');
            if (vb && vb !== '—' && vb !== '0') brandModelParts.push(vb);
            if (vm && vm !== '—' && vm !== '0') brandModelParts.push(vm);
            setText('viewJOBrandModel', brandModelParts.length ? brandModelParts.join(' ') : '—');
            setText('viewJOVehicleBrand', vb);
            setText('viewJOVehicleModel', vm);

            setText('viewJOYearModel', val(joData.year_model));
            setText('viewJOEngineNo', val(joData.engine_number));
            setText('viewJOChassisNo', val(joData.chassis_number));
            setText('viewJOContact', val(joData.contact_number));
            setText('viewJOOrNo', val(joData.or_number));

            setText('viewJOService', val(joData.service_type));
            setText('viewJOParts', val(joData.parts));
            setText('viewJOMechanic', val(joData.mechanic, 'Unassigned'));
            setText('viewJODuration', joData.estimated_duration ? joData.estimated_duration + ' mins' : '—');
            setText('viewJOWorkflow', val(joData.workflow_status));
            setText('viewJOPayment', val(joData.payment_status));
            setText('viewJOPayMethod', val(joData.payment_method, 'Cash'));

            setText('viewJOTotal', fmt(joData.total || 0));
            setText('viewJOPaid', fmt(joData.paid || 0));
            setText('viewJOBalance', fmt(joData.balance || 0));
            setText('viewJOCreated', joData.created_at
                ? new Date(joData.created_at).toLocaleString('en-PH', {dateStyle:'medium', timeStyle:'short'})
                : '—');

            setText('viewJORemarks', val(joData.remarks || joData.staff_remarks || joData.service_description));

            // Enhance status badges
            var wfEl = document.getElementById('viewJOWorkflow');
            if (wfEl) {
                var wf = (joData.workflow_status || '').toLowerCase();
                var wfColor = '#475569';
                var wfBg = '#f1f5f9';
                if (wf === 'completed' || wf === 'released' || wf === 'done') { wfColor = '#15803d'; wfBg = '#dcfce7'; }
                else if (wf === 'in progress' || wf === 'in_progress') { wfColor = '#0369a1'; wfBg = '#e0f2fe'; }
                else if (wf === 'pending') { wfColor = '#b45309'; wfBg = '#fef3c7'; }
                else if (wf === 'cancelled' || wf === 'rejected') { wfColor = '#b91c1c'; wfBg = '#fee2e2'; }
                wfEl.style.color = wfColor;
                wfEl.style.backgroundColor = wfBg;
            }

            var payEl = document.getElementById('viewJOPayment');
            if (payEl) {
                var ps = (joData.payment_status || '').toLowerCase();
                var pColor = '#475569';
                var pBg = '#f1f5f9';
                if (ps === 'paid') { pColor = '#15803d'; pBg = '#dcfce7'; }
                else if (ps === 'partial') { pColor = '#b45309'; pBg = '#fef3c7'; }
                else if (ps === 'unpaid') { pColor = '#b91c1c'; pBg = '#fee2e2'; }
                payEl.style.color = pColor;
                payEl.style.backgroundColor = pBg;
            }

            var modal = document.getElementById('viewJobOrderModal');
            if (modal) {
                // Position modal relative to .main content area (EXCLUDES sidebar).
                // We read the actual bounding rect of .main so the backdrop
                // covers only the content area — sidebar stays fully visible.
                var mainEl = document.querySelector('main.main') || document.querySelector('.main');
                var isCollapsed = document.body.classList.contains('sidebar-collapsed');
                var defaultSidebarW = isCollapsed ? 70 : 250;
                var mLeft = (window.innerWidth >= 992) ? defaultSidebarW : 0;
                var mTop = (window.innerWidth >= 992) ? 70 : 60;
                var mWidth = window.innerWidth - mLeft;
                var mHeight = window.innerHeight - mTop;
                if (mainEl) {
                    var r = mainEl.getBoundingClientRect();
                    if (r.left > 0) mLeft = Math.round(r.left);
                    if (r.top > 0) mTop = Math.round(r.top);
                    if (r.width > 0) mWidth = Math.round(r.width);
                    if (r.height > 0) mHeight = Math.round(r.height);
                }

                // Keep modal inside the DOM where it is (inside .main is fine —
                // the sidebar's higher z-index naturally keeps it on top).
                modal.style.setProperty('position',         'fixed',              'important');
                modal.style.setProperty('left',             mLeft   + 'px',       'important');
                modal.style.setProperty('top',              mTop    + 'px',       'important');
                modal.style.setProperty('width',            mWidth  + 'px',       'important');
                modal.style.setProperty('height',           mHeight + 'px',       'important');
                modal.style.setProperty('right',            'auto',               'important');
                modal.style.setProperty('bottom',           'auto',               'important');
                modal.style.setProperty('display',          'flex',               'important');
                modal.style.setProperty('align-items',      'center',             'important');
                modal.style.setProperty('justify-content',  'center',             'important');
                modal.style.setProperty('z-index',          '99999',              'important');
                modal.style.setProperty('padding',          '16px',               'important');
                modal.style.setProperty('box-sizing',       'border-box',         'important');
                modal.style.setProperty('overflow-y',       'auto',               'important');
                modal.style.setProperty('background',       'rgba(15,23,42,0.65)','important');
                modal.style.setProperty('backdrop-filter',  'blur(4px)',          'important');

                // Scroll body to top
                var scrollBody = modal.querySelector('.vjo-scroll-body');
                if (scrollBody) scrollBody.scrollTop = 0;
            }
        }

        function printJobOrderReceiptFromModal() {
            if (_currentViewJORef) {
                printJobOrderReceipt(0, _currentViewJORef);
            }
        }
        
        function closeViewJobOrderModal() {
            var m = document.getElementById('viewJobOrderModal');
            if (m) m.style.setProperty('display', 'none', 'important');
        }
        
        // Update Status Modal
        function openUpdateStatusModal(joId, currentStatus, source) {
            document.getElementById('updateStatusJOId').value = joId;
            document.getElementById('updateStatusJOSource').value = source;
            document.getElementById('updateStatusJORef').textContent = 'JO #' + joId;
            document.getElementById('updateStatusCurrent').textContent = currentStatus || 'Pending';
            
            var select = document.getElementById('updateStatusSelect');
            select.value = '';
            
            // Show/hide rejection remarks based on selection
            select.onchange = function() {
                var remarksDiv = document.getElementById('updateStatusRemarksDiv');
                var remarksField = document.getElementById('updateStatusRemarks');
                if (this.value === 'Rejected') {
                    remarksDiv.style.display = 'block';
                    remarksField.required = true;
                } else {
                    remarksDiv.style.display = 'none';
                    remarksField.required = false;
                }
            };
            
            document.getElementById('updateStatusModal').style.display = 'flex';
        }
        
        function closeUpdateStatusModal() {
            document.getElementById('updateStatusModal').style.display = 'none';
        }
        
        // Adjust Job Order Modal
        function openAdjustJobOrderModal(joData) {
            document.getElementById('adjustJOId').value = joData.id || '';
            document.getElementById('adjustJOSource').value = joData.source || 'job_orders';
            document.getElementById('adjustJORef').textContent = joData.jo_ref || '';
            document.getElementById('adjustJOCustomer').value = joData.customer || '';
            document.getElementById('adjustJOPlate').value = joData.vehicle_plate || '';
            document.getElementById('adjustJOType').value = joData.vehicle_type || '';
            document.getElementById('adjustJOService').value = joData.service_type || '';
            document.getElementById('adjustJODescription').value = joData.service_description || '';
            document.getElementById('adjustJOMechanic').value = joData.mechanic || '';
            document.getElementById('adjustJOCost').value = joData.total || '';
            document.getElementById('adjustJODuration').value = joData.estimated_duration || '';
            
            document.getElementById('adjustJobOrderModal').style.display = 'flex';
        }
        
        function closeAdjustJobOrderModal() {
            document.getElementById('adjustJobOrderModal').style.display = 'none';
        }
        
        // Print Job Order Receipt
        function printJobOrderReceipt(joId, joRef) {
            // joRef may be '#688' (fragment) if job_order_id is null in DB.
            // Browsers strip '#...' from URLs, so use numeric joId in that case.
            var rid = (joRef && joRef.charAt(0) !== '#') ? encodeURIComponent(joRef) : joId;
            var url = 'receipt.php?id=' + rid + '&type=job_order';
            window.open(url, '_blank');
        }
        
        var currentMTData = null;

        // Print Merchandise Receipt
        function printMerchandiseReceipt(txnId) {
            var url = 'receipt.php?id=' + encodeURIComponent(txnId) + '&type=merchandise';
            window.open(url, '_blank');
        }
        window.printMerchandiseReceipt = printMerchandiseReceipt;
        
        // View Merchandise Transaction Details
        function viewMerchandiseDetails(txnId) {
            ['viewJobOrderModal', 'viewMerchandiseModal', 'updateStatusModal', 'adjustJobOrderModal', 'txnRequestModal', 'requestAdjustModal', 'requestVoidModal', 'paymentSettleModal'].forEach(function(id) {
                const m = document.getElementById(id);
                if (m) m.style.display = 'none';
            });
            if (!txnId) {
                showTxnAlert('Invalid transaction ID', 'error');
                return;
            }
            
            // Show modal in loading state
            var itemsBody = document.getElementById('viewMTItemsBody');
            if (itemsBody) {
                itemsBody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:16px;color:#94a3b8;"><i class="fas fa-spinner fa-spin"></i> Loading transaction details...</td></tr>';
            }
            document.getElementById('viewMerchandiseModal').style.display = 'flex';

            // Fetch transaction details via AJAX
            fetch('../backend/get_merchandise_transaction_details.php?id=' + encodeURIComponent(txnId))
                .then(function(response) { return response.json(); })
                .then(function(data) {
                    if (data.success && data.transaction) {
                        const txn = data.transaction;
                        currentMTData = txn;
                        
                        // Populate modal fields
                        document.getElementById('viewMTxnRef').textContent = (txn.transaction_id || '—');
                        document.getElementById('viewMTCustomer').textContent = txn.customer_name || 'Walk-in Customer';
                        document.getElementById('viewMTShift').textContent = (txn.shift_name || txn.shift_period) || '—';
                        document.getElementById('viewMTDate').textContent = txn.transaction_date || '—';
                        document.getElementById('viewMTPayMethod').textContent = txn.payment_method || 'Cash';
                        document.getElementById('viewMTPayStatus').innerHTML = txn.payment_status_badge || '—';
                        document.getElementById('viewMTSubtotal').textContent = txn.subtotal_display || '₱0.00';
                        document.getElementById('viewMTVAT').textContent = txn.vat_display || '₱0.00';

                        var ptsRedeemed = parseInt(txn.loyalty_points_redeemed || 0, 10);
                        var discAmt = parseFloat(txn.loyalty_discount_amount || txn.discount_amount || 0);
                        var loyaltyRow = document.getElementById('viewMTLoyaltyRow');
                        if (loyaltyRow) {
                            if (ptsRedeemed > 0 || discAmt > 0) {
                                loyaltyRow.style.display = 'flex';
                                var loyaltyPtsEl = document.getElementById('viewMTLoyaltyPoints');
                                if (loyaltyPtsEl) loyaltyPtsEl.textContent = ptsRedeemed + ' pts (₱' + discAmt.toFixed(2) + ')';
                            } else {
                                loyaltyRow.style.display = 'none';
                            }
                        }

                        document.getElementById('viewMTTotal').textContent = txn.total_display || '₱0.00';
                        document.getElementById('viewMTPaid').textContent = txn.paid_display || '₱0.00';
                        
                        var balanceDue = parseFloat(txn.balance_due || 0);
                        var balanceEl = document.getElementById('viewMTBalance');
                        if (balanceDue > 0.009) {
                            balanceEl.textContent = '₱' + balanceDue.toFixed(2);
                            balanceEl.style.color = '#dc2626';
                        } else {
                            balanceEl.textContent = '₱0.00 (Fully Settled)';
                            balanceEl.style.color = '#166534';
                        }

                        document.getElementById('viewMTRemarks').textContent = txn.remarks || '—';
                        document.getElementById('viewMTStaff').textContent = txn.staff_name || '—';
                        
                        // Combined Transaction - Job Order Details handling
                        var isCombined = (txn.transaction_type === 'combined') || (txn.job_order_service && txn.job_order_service !== '');
                        var joSection = document.getElementById('viewMTJobOrderSection');
                        var itemsHeading = document.getElementById('viewMTItemsHeading');
                        if (joSection) {
                            if (isCombined) {
                                joSection.style.display = 'block';
                                var elServ = document.getElementById('viewMTJOService'); if (elServ) elServ.textContent = txn.job_order_service || '—';
                                var elMech = document.getElementById('viewMTJOMechanic'); if (elMech) elMech.textContent = txn.job_order_mechanic_name || '—';
                                var elPlate = document.getElementById('viewMTJOPlate'); if (elPlate) elPlate.textContent = txn.job_order_vehicle_plate || '—';
                                var vehicleInfo = [txn.job_order_vehicle_brand, txn.job_order_vehicle_model, txn.job_order_vehicle_type].filter(Boolean).join(' ');
                                var elVeh = document.getElementById('viewMTJOVehicle'); if (elVeh) elVeh.textContent = vehicleInfo || '—';
                                if (itemsHeading) itemsHeading.innerHTML = '<i class="fas fa-boxes" style="margin-right:6px;color:#002F70;"></i> Purchased Items (Services & Merchandise)';
                            } else {
                                joSection.style.display = 'none';
                                if (itemsHeading) itemsHeading.innerHTML = '<i class="fas fa-boxes" style="margin-right:6px;color:#002F70;"></i> Purchased Items';
                            }
                        }

                        // Populate items table (NO ACTION BUTTONS)
                        var items = txn.items || [];
                        var countBadge = document.getElementById('viewMTItemCountBadge');
                        if (countBadge) countBadge.textContent = items.length + ' item' + (items.length === 1 ? '' : 's');

                        if (items.length > 0) {
                            itemsBody.innerHTML = items.map(function(item) {
                                var qty = parseFloat(item.quantity || 0);
                                var qtyDisplay = (qty % 1 === 0) ? parseInt(qty) : qty;
                                var unit = item.unit || 'pc';
                                var unitPrice = parseFloat(item.unit_price || 0);
                                var subtotal = parseFloat(item.subtotal || (qty * unitPrice));
                                var sku = item.sku || '—';
                                var cat = (item.category || 'General').replace(/</g, '&lt;');
                                var name = (item.product_name || '—').replace(/</g, '&lt;');

                                return '<tr style="border-bottom:1px solid #f1f5f9;">' +
                                    '<td style="padding:7px 8px;font-weight:700;color:#1e293b;word-break:break-word;font-size:12px;line-height:1.3;">' + name + '</td>' +
                                    '<td style="padding:7px 8px;color:#64748b;font-size:11px;word-break:break-word;line-height:1.3;">' + (sku !== '—' ? '<span style="font-family:monospace;font-weight:600;color:#002F70;">' + sku.replace(/</g, '&lt;') + '</span><br>' : '') + cat + '</td>' +
                                    '<td style="padding:7px 6px;text-align:center;font-weight:700;color:#334155;font-size:12px;">' + qtyDisplay + ' <span style="font-size:11px;color:#64748b;font-weight:500;">' + unit.replace(/</g, '&lt;') + '</span></td>' +
                                    '<td style="padding:7px 8px;text-align:right;color:#475569;font-weight:600;font-size:12px;white-space:nowrap;">₱' + unitPrice.toFixed(2) + '</td>' +
                                    '<td style="padding:7px 8px;text-align:right;font-weight:800;color:#002F70;font-size:12px;white-space:nowrap;">₱' + subtotal.toFixed(2) + '</td>' +
                                '</tr>';
                            }).join('');
                        } else {
                            itemsBody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:16px;color:#94a3b8;">No items found</td></tr>';
                        }
                        
                        // Configure Top Action Bar
                        var valStatus = (txn.validation_status || '').toLowerCase();
                        var isVoided = ['voided', 'cancelled', 'canceled'].indexOf(valStatus) !== -1;
                        var isAdjusted = (valStatus === 'adjusted');
                        var pendingReq = txn.pending_request;
                        var settleBtn = document.getElementById('viewMTSettlePayBtn');
                        var adjustBtn = document.getElementById('viewMTAdjustBtn');
                        var voidBtn = document.getElementById('viewMTVoidBtn');
                        var reprintBtn = document.getElementById('viewMTReprintBtn');
                        var statusBadges = document.getElementById('viewMTStatusBadges');

                        if (statusBadges) statusBadges.innerHTML = '';

                        if (isVoided) {
                            if (settleBtn) settleBtn.style.display = 'none';
                            if (adjustBtn) adjustBtn.style.display = 'none';
                            if (voidBtn) voidBtn.style.display = 'none';
                            if (reprintBtn) reprintBtn.style.display = 'none';
                            if (statusBadges) statusBadges.innerHTML = '<span style="padding:4px 10px;border-radius:6px;background:#fee2e2;color:#991b1b;font-size:11px;font-weight:800;"><i class="fas fa-ban"></i> VOIDED</span>';
                        } else if (isAdjusted) {
                            if (settleBtn) settleBtn.style.display = (balanceDue > 0.009) ? 'inline-flex' : 'none';
                            if (adjustBtn) adjustBtn.style.display = 'none';
                            if (voidBtn) voidBtn.style.display = 'none';
                            if (reprintBtn) reprintBtn.style.display = 'inline-flex';
                            if (statusBadges) statusBadges.innerHTML = '<span style="padding:4px 10px;border-radius:6px;background:#ede9fe;color:#4338ca;font-size:11px;font-weight:800;"><i class="fas fa-check-circle"></i> ADJUSTED</span>';
                        } else if (pendingReq) {
                            if (settleBtn) settleBtn.style.display = 'none';
                            if (adjustBtn) adjustBtn.style.display = 'none';
                            if (voidBtn) voidBtn.style.display = 'none';
                            if (reprintBtn) reprintBtn.style.display = 'inline-flex';
                            var reqColor = (pendingReq.request_type === 'Void') ? '#dc2626' : '#d97706';
                            var reqBg = (pendingReq.request_type === 'Void') ? '#fee2e2' : '#fef3c7';
                            if (statusBadges) statusBadges.innerHTML = '<span style="padding:4px 10px;border-radius:6px;background:' + reqBg + ';color:' + reqColor + ';font-size:11px;font-weight:800;"><i class="fas fa-clock"></i> ' + (pendingReq.request_type ? pendingReq.request_type.toUpperCase() : 'REQUEST') + ' PENDING APPROVAL</span>';
                        } else {
                            // Normal Active Transaction
                            if (settleBtn) settleBtn.style.display = (balanceDue > 0.009) ? 'inline-flex' : 'none';
                            if (adjustBtn) adjustBtn.style.display = 'inline-flex';
                            if (voidBtn) voidBtn.style.display = 'inline-flex';
                            if (reprintBtn) reprintBtn.style.display = 'inline-flex';
                        }
                    } else {
                        showTxnAlert(data.error || 'Failed to load transaction details', 'error');
                        closeViewMerchandiseModal();
                    }
                })
                .catch(function(error) {
                    console.error('Error fetching merchandise details:', error);
                    showTxnAlert('Network error: ' + error.message, 'error');
                    closeViewMerchandiseModal();
                });
        }
        
